import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  STUDENT = 'STUDENT',
}

export interface User {
  id: string;
  name: string;
  password?: string; // Optional for security in frontend list display
  color: string; // Tailwind color class or hex
  role: UserRole;
}

export interface ShiftDay {
  date: string; // YYYY-MM-DD
  signups: string[]; // User IDs of students who signed up
  confirmedUserId?: string; // ID of the student actually assigned
  isClosed?: boolean; // Is clinic closed manually
}

export interface ShiftMap {
  [date: string]: ShiftDay;
}

export interface AppSettings {
  adminPassword?: string; // Should be handled carefully
  holidays: string[]; // List of YYYY-MM-DD strings
}

export interface AppData {
  users: User[];
  shifts: ShiftMap;
  settings: AppSettings;
}

export interface ApiPayload {
  action: 'getData' | 'login' | 'toggleSignup' | 'assignShift' | 'updateSettings' | 'manageUser' | 'setHoliday';
  payload?: any;
}

import { GAS_API_URL } from '../constants';
import { AppData, ApiPayload, UserRole } from '../types';

// Mock data for initial load if API fails or is empty (for demonstration stability)
const MOCK_DATA: AppData = {
  users: [
    { id: 'u1', name: '王小明', color: 'bg-blue-100 text-blue-800', role: UserRole.STUDENT },
    { id: 'u2', name: '李大華', color: 'bg-green-100 text-green-800', role: UserRole.STUDENT },
    { id: 'u3', name: '張小美', color: 'bg-pink-100 text-pink-800', role: UserRole.STUDENT },
  ],
  shifts: {},
  settings: {
    holidays: ['2024-01-01', '2024-02-09', '2024-02-10'], // Example
    adminPassword: 'admin',
  },
};

export const fetchAppData = async (): Promise<AppData> => {
  try {
    // GAS often uses GET for retrieving data to avoid CORS preflight issues on simple requests
    const response = await fetch(`${GAS_API_URL}?action=getData`);
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    const data = await response.json();

    // Robustness: ensure basic structure exists
    if (!data.users || !data.shifts) {
      console.warn("API returned incomplete data, using mock/partial data", data);
      return { ...MOCK_DATA, ...data };
    }
    return data;
  } catch (error) {
    console.error("Failed to fetch data from GAS:", error);
    // Fallback for demo purposes if the user's specific URL isn't configured with the right backend script yet
    console.warn("Falling back to local mock data.");
    return MOCK_DATA;
  }
};

export const sendAction = async (payload: ApiPayload): Promise<AppData | null> => {
  try {
    // Using POST for actions. 
    // Note: Google Apps Script Web App must implement doPost(e) and return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
    // And handle CORS headers appropriately.

    // For many GAS implementations, avoiding CORS preflight via text/plain is a common hack, 
    // but we will try standard JSON first.
    const response = await fetch(GAS_API_URL, {
      method: 'POST',
      // Using text/plain to prevent CORS preflight OPTIONS request which GAS doesn't handle natively without workarounds
      headers: {
        'Content-Type': 'text/plain;charset=utf-8', 
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      throw new Error(`Server error: ${response.status}`);
    }

    const result = await response.json();
    return result; // Expecting the updated full dataset back to sync state
  } catch (error) {
    console.error("Action failed:", error);
    return null;
  }
};

import React, { useMemo } from 'react';
import { AppData, User, ShiftDay, UserRole } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';
import { Check, X, Lock, AlertCircle } from 'lucide-react';

interface CalendarProps {
  currentDate: Date;
  data: AppData;
  currentUser: User | null;
  onMonthChange: (increment: number) => void;
  onDateClick: (dateStr: string) => void;
  onAdminAction?: (dateStr: string, action: 'confirm' | 'close' | 'clear', userId?: string) => void;
}

const Calendar: React.FC<CalendarProps> = ({ 
  currentDate, 
  data, 
  currentUser, 
  onMonthChange, 
  onDateClick,
  onAdminAction
}) => {

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay(); // 0 is Sunday

  // Helper to format YYYY-MM-DD
  const formatDate = (y: number, m: number, d: number) => {
    return `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  };

  const getDayDetails = (day: number) => {
    const dateStr = formatDate(year, month, day);
    const dateObj = new Date(year, month, day);
    const dayOfWeek = dateObj.getDay();

    // Check holiday
    const isHoliday = data.settings.holidays.includes(dateStr);
    const isSunday = dayOfWeek === 0;
    const isSaturday = dayOfWeek === 6;

    // Time & Color Logic
    let timeText = '10:00 - 18:00';
    let dateColorClass = 'text-gray-700'; // Default

    if (isSunday || isHoliday) {
      timeText = '10:00 - 17:00';
      dateColorClass = 'text-red-600 font-bold';
    } else if (isSaturday) {
      dateColorClass = 'text-green-600 font-bold';
    }

    // Shift Info
    const shift: ShiftDay | undefined = data.shifts[dateStr];
    const signups = shift?.signups || [];
    const confirmedId = shift?.confirmedUserId;
    const isClosed = shift?.isClosed;

    return {
      dateStr,
      day,
      dayOfWeek,
      isHoliday,
      isSunday,
      timeText,
      dateColorClass,
      signups,
      confirmedId,
      isClosed
    };
  };

  const renderCellContent = (details: ReturnType<typeof getDayDetails>) => {
    const { dateStr, signups, confirmedId, isClosed } = details;

    if (isClosed) {
      return (
        <div className="flex flex-col items-center justify-center h-full bg-gray-100 rounded opacity-75">
          <span className="text-gray-500 font-bold text-lg">休診</span>
        </div>
      );
    }

    // Logic for displaying the worker
    let displayWorker = null;

    if (confirmedId) {
      // Admin has confirmed someone
      const user = data.users.find(u => u.id === confirmedId);
      if (user) {
        displayWorker = (
          <div className={`mt-2 px-2 py-1 rounded text-sm font-medium w-full text-center truncate shadow-sm border border-black/5 ${user.color}`}>
             <span className="mr-1">★</span>{user.name}
          </div>
        );
      }
    } else if (signups.length === 0) {
      // No one signed up
      displayWorker = (
        <div className="mt-2 px-2 py-1 rounded text-sm font-medium w-full text-center bg-gray-200 text-gray-500 truncate">
          {DEFAULT_WORKER_NAME}
        </div>
      );
    } else if (signups.length === 1) {
      // Exactly one person
      const user = data.users.find(u => u.id === signups[0]);
      if (user) {
        displayWorker = (
          <div className={`mt-2 px-2 py-1 rounded text-sm font-medium w-full text-center truncate shadow-sm ${user.color}`}>
            {user.name}
          </div>
        );
      }
    } else {
      // Multiple signups, pending confirmation
      displayWorker = (
        <div className="mt-2 flex flex-col gap-1 w-full">
          <div className="px-1 py-0.5 rounded text-xs bg-yellow-100 text-yellow-800 text-center border border-yellow-300">
             {signups.length} 人報名 (待定)
          </div>
          {/* Admin view sees list, Student sees concise status */}
          <div className="flex flex-wrap gap-1 justify-center">
             {signups.map(uid => {
               const u = data.users.find(usr => usr.id === uid);
               return u ? <span key={uid} className={`w-2 h-2 rounded-full ${u.color.split(' ')[0].replace('bg-', 'bg-')}`}></span> : null;
             })}
          </div>
        </div>
      );
    }

    return (
      <div className="flex flex-col h-full w-full">
        {displayWorker}

        {/* Interaction Area for Current User */}
        {currentUser?.role === UserRole.STUDENT && (
          <div className="mt-auto pt-2 flex justify-center">
            {signups.includes(currentUser.id) ? (
               <div className="flex items-center text-green-600 text-xs font-bold">
                 <Check size={14} className="mr-1" /> 已報名
               </div>
            ) : (
              <span className="text-gray-300 text-xs hover:text-gray-500 transition-colors">點擊報名</span>
            )}
          </div>
        )}
      </div>
    );
  };

  // Generating Grid Cells
  const calendarCells = [];

  // Empty slots for previous month
  for (let i = 0; i < firstDayOfMonth; i++) {
    calendarCells.push(<div key={`empty-${i}`} className="bg-gray-50/50 min-h-[120px] border border-gray-100" />);
  }

  // Actual days
  for (let d = 1; d <= daysInMonth; d++) {
    const details = getDayDetails(d);

    // Interaction Wrapper
    const isInteractable = currentUser?.role === UserRole.STUDENT && !details.isClosed && !details.confirmedId;
    const isAdmin = currentUser?.role === UserRole.ADMIN;

    // Highlight if current user signed up
    const isSignedUp = details.signups.includes(currentUser?.id || '');

    calendarCells.push(
      <div 
        key={details.dateStr} 
        onClick={() => {
           if (isAdmin) {
             onDateClick(details.dateStr); // Opens admin modal
           } else if (isInteractable) {
             onDateClick(details.dateStr); // Toggles signup
           }
        }}
        className={`
          relative min-h-[120px] p-2 border border-gray-200 transition-all duration-200 flex flex-col
          ${isInteractable ? 'cursor-pointer hover:bg-blue-50 hover:shadow-md' : ''}
          ${isAdmin ? 'cursor-pointer hover:bg-gray-50' : ''}
          ${isSignedUp && !isAdmin ? 'bg-blue-50 ring-2 ring-inset ring-blue-200' : 'bg-white'}
        `}
      >
        {/* Date Header */}
        <div className="flex justify-between items-start mb-1">
          <span className={`text-xl ${details.dateColorClass}`}>{d}</span>
          <span className={`text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-600`}>
             {details.timeText}
          </span>
        </div>

        {/* Holiday Label */}
        {details.isHoliday && (
          <div className="absolute top-10 right-2 text-xs text-red-500 font-bold bg-red-50 px-1 rounded">
             國定假日
          </div>
        )}

        {/* Content */}
        {renderCellContent(details)}

      </div>
    );
  }

  return (
    <div className="w-full bg-white shadow-lg rounded-xl overflow-hidden border border-gray-200">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 bg-white border-b border-gray-200">
         <button onClick={() => onMonthChange(-1)} className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600">
           ◀ 上個月
         </button>
         <h2 className="text-2xl font-bold text-gray-800">
           {year} 年 {month + 1} 月
         </h2>
         <button onClick={() => onMonthChange(1)} className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-600">
           下個月 ▶
         </button>
      </div>

      {/* Weekdays */}
      <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
        {WEEKDAYS.map((day, idx) => (
          <div key={day} className={`py-3 text-center font-bold text-sm ${idx === 0 ? 'text-red-500' : idx === 6 ? 'text-green-600' : 'text-gray-600'}`}>
            週{day}
          </div>
        ))}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-7">
        {calendarCells}
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState } from 'react';
import { AppData, User, UserRole } from '../types';
import { TAILWIND_COLORS } from '../constants';
import { Plus, Trash2, Save, Calendar, ShieldAlert } from 'lucide-react';

interface AdminPanelProps {
  data: AppData;
  onUpdateUser: (action: 'add' | 'delete', user?: User) => void;
  onUpdateSettings: (newSettings: AppData['settings']) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ data, onUpdateUser, onUpdateSettings }) => {
  const [activeTab, setActiveTab] = useState<'users' | 'settings'>('users');

  // New User State
  const [newName, setNewName] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newColor, setNewColor] = useState(TAILWIND_COLORS[0].value);

  // Settings State
  const [holidayInput, setHolidayInput] = useState(data.settings.holidays.join('\n'));
  const [adminPassInput, setAdminPassInput] = useState(data.settings.adminPassword || '');

  const handleAddUser = () => {
    if (!newName || !newPassword) return alert("請輸入姓名與密碼");
    const newUser: User = {
      id: `u_${Date.now()}`,
      name: newName,
      password: newPassword, // Note: Stored in plain text as per basic req, ideally hashed
      color: newColor,
      role: UserRole.STUDENT
    };
    onUpdateUser('add', newUser);
    setNewName('');
    setNewPassword('');
  };

  const handleSaveSettings = () => {
    const holidays = holidayInput
      .split('\n')
      .map(s => s.trim())
      .filter(s => s.match(/^\d{4}-\d{2}-\d{2}$/)); // Basic validation YYYY-MM-DD

    onUpdateSettings({
      adminPassword: adminPassInput,
      holidays: holidays
    });
    alert("設定已儲存！");
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
      <div className="flex border-b border-gray-200">
        <button 
          onClick={() => setActiveTab('users')}
          className={`flex-1 py-4 font-bold text-center transition-colors ${activeTab === 'users' ? 'bg-blue-50 text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          人員管理
        </button>
        <button 
          onClick={() => setActiveTab('settings')}
          className={`flex-1 py-4 font-bold text-center transition-colors ${activeTab === 'settings' ? 'bg-blue-50 text-blue-600 border-b-2 border-blue-600' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          系統設定 (假日/密碼)
        </button>
      </div>

      <div className="p-6">
        {activeTab === 'users' && (
          <div className="space-y-6">
            <h3 className="text-lg font-bold text-gray-800 border-l-4 border-blue-500 pl-3">新增工讀生</h3>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end bg-gray-50 p-4 rounded-lg">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">姓名</label>
                <input 
                  type="text" 
                  value={newName} 
                  onChange={e => setNewName(e.target.value)}
                  className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="姓名"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">登入密碼</label>
                <input 
