export default AdminPanel;

import React from 'react';
import { AppData, User } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';

interface PrintViewProps {
  currentDate: Date;
  data: AppData;
  onClose: () => void;
}

const PrintView: React.FC<PrintViewProps> = ({ currentDate, data, onClose }) => {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  // Generate matrix
  const weeks = [];
  let currentWeek = new Array(7).fill(null);

  // Fill initial blanks
  for (let i = 0; i < firstDayOfMonth; i++) {
    currentWeek[i] = null;
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const dayOfWeek = new Date(year, month, d).getDay();
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const shift = data.shifts[dateStr];

    // Determine content
    let content = DEFAULT_WORKER_NAME;
    if (shift?.isClosed) content = "休診";
    else if (shift?.confirmedUserId) {
      const u = data.users.find(user => user.id === shift.confirmedUserId);
      if (u) content = u.name;
    } else if (shift?.signups && shift.signups.length === 1) {
      const u = data.users.find(user => user.id === shift.signups[0]);
      if (u) content = u.name;
    } else if (shift?.signups && shift.signups.length > 1) {
      content = "待確認";
    }

    currentWeek[dayOfWeek] = { day: d, content };

    if (dayOfWeek === 6 || d === daysInMonth) {
      weeks.push(currentWeek);
      currentWeek = new Array(7).fill(null);
    }
  }

  return (
    <div className="fixed inset-0 bg-white z-50 overflow-auto p-8">
      <div className="max-w-4xl mx-auto">
        <div className="flex justify-between items-center mb-8 no-print">
           <h1 className="text-2xl font-bold">列印預覽</h1>
           <div className="flex gap-4">
             <button onClick={() => window.print()} className="bg-blue-600 text-white px-4 py-2 rounded font-bold">列印</button>
             <button onClick={onClose} className="bg-gray-300 text-gray-800 px-4 py-2 rounded font-bold">關閉</button>
           </div>
        </div>

        <div className="border-2 border-black p-4">
          <h2 className="text-3xl font-bold text-center mb-6">{year} 年 {month + 1} 月 放射科工讀生班表</h2>

          <table className="w-full border-collapse border border-black">
            <thead>
              <tr>
                {WEEKDAYS.map(d => (
                  <th key={d} className="border border-black p-2 bg-gray-100 w-[14.28%] text-center font-bold">週{d}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {weeks.map((week, idx) => (
                <tr key={idx}>
                  {week.map((cell: any, cIdx: number) => {
                    if (!cell) return <td key={cIdx} className="border border-black p-4 h-24 bg-gray-50"></td>;
                    return (
                      <td key={cIdx} className="border border-black p-2 h-24 align-top relative">
                        <span className="font-bold text-lg block mb-1">{cell.day}</span>
                        <div className="flex justify-center items-center h-12">
                           <span className="text-lg font-medium">{cell.content}</span>
                        </div>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

