import React, { useState, useEffect } from 'react';
import { User, AppData, UserRole } from './types';
import { fetchAppData, sendAction } from './services/api';
import Login from './components/Login';
import Calendar from './components/Calendar';
import AdminPanel from './components/AdminPanel';
import PrintView from './components/PrintView';
import { LogOut, Printer, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [data, setData] = useState<AppData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [syncing, setSyncing] = useState<boolean>(false);
  const [currentDate, setCurrentDate] = useState<Date>(new Date());
  const [showPrintView, setShowPrintView] = useState(false);

  // Admin Modal State
  const [selectedAdminDate, setSelectedAdminDate] = useState<string | null>(null);

  // Initial Data Load
  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setLoading(false);
  };

  const handleSync = async () => {
    setSyncing(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setSyncing(false);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setSelectedAdminDate(null);
  };

  // Calendar Actions
  const handleDateClick = async (dateStr: string) => {
    if (!currentUser || !data) return;

    if (currentUser.role === UserRole.STUDENT) {
      // Toggle Signup
      const shift = data.shifts[dateStr];
      if (shift?.isClosed || shift?.confirmedUserId) return; // Locked

      const currentSignups = shift?.signups || [];
      const isSignedUp = currentSignups.includes(currentUser.id);

      // Optimistic Update
      const newSignups = isSignedUp 
        ? currentSignups.filter(id => id !== currentUser.id)
        : [...currentSignups, currentUser.id];

      const newData = { ...data, shifts: { ...data.shifts, [dateStr]: { ...shift, date: dateStr, signups: newSignups } } };
      setData(newData);

      // API Call
      await sendAction({
        action: 'toggleSignup',
        payload: { date: dateStr, userId: currentUser.id }
      });
      // Optionally re-fetch to confirm consistency, but simple toggle is okay optimistically
    } else if (currentUser.role === UserRole.ADMIN) {
      // Open Admin Modal for this date
      setSelectedAdminDate(dateStr);
    }
  };

  // Admin Shift Management
  const handleAdminShiftAction = async (action: 'confirm' | 'close' | 'clear', targetUserId?: string) => {
    if (!selectedAdminDate || !data) return;

    // Optimistic Update
    const shift = data.shifts[selectedAdminDate] || { date: selectedAdminDate, signups: [] };
    let newShift = { ...shift };

    if (action === 'confirm' && targetUserId) {
      newShift.confirmedUserId = targetUserId;
      newShift.isClosed = false;
    } else if (action === 'close') {
      newShift.isClosed = !newShift.isClosed;
      newShift.confirmedUserId = undefined;
    } else if (action === 'clear') {
      newShift.confirmedUserId = undefined;
      newShift.isClosed = false;
    }

    const newData = { ...data, shifts: { ...data.shifts, [selectedAdminDate]: newShift } };
    setData(newData);
    setSelectedAdminDate(null); // Close modal

    // API Call
    await sendAction({
      action: 'assignShift',
      payload: { date: selectedAdminDate, ...newShift }
    });
  };

  // Admin Panel Updates
  const handleUserUpdate = async (action: 'add' | 'delete', user?: User) => {
    if (!data) return;
    let newUsers = [...data.users];
    if (action === 'add' && user) {
      newUsers.push(user);
    } else if (action === 'delete' && user) {
      newUsers = newUsers.filter(u => u.id !== user.id);
    }

    setData({ ...data, users: newUsers });

    await sendAction({
      action: 'manageUser',
      payload: { type: action, user }
    });
  };

  const handleSettingsUpdate = async (newSettings: AppData['settings']) => {
    if (!data) return;
    setData({ ...data, settings: newSettings });

    await sendAction({
      action: 'updateSettings',
      payload: newSettings
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">載入班表資料中 (Connecting to Google Sheet)...</p>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={data?.users || []} adminPassword={data?.settings.adminPassword} onLogin={handleLogin} />;
  }

  if (showPrintView && data) {
    return <PrintView currentDate={currentDate} data={data} onClose={() => setShowPrintView(false)} />;
  }

  return (
    <div className="min-h-screen pb-12">
      {/* Top Navigation */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-2">
              <div className={`w-3 h-3 rounded-full ${currentUser.role === UserRole.ADMIN ? 'bg-purple-500' : 'bg-blue-500'}`}></div>
              <span className="font-bold text-gray-800">
                {currentUser.name} ({currentUser.role === UserRole.ADMIN ? '管理員' : '工讀生'})
              </span>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleSync}
                disabled={syncing}
                className="p-2 text-gray-500 hover:text-blue-600 hover:bg-gray-100 rounded-full transition-all disabled:animate-spin"
                title="同步資料"
              >
                <RefreshCw size={20} />
              </button>
              <button 
                onClick={() => setShowPrintView(true)}
                className="p-2 text-gray-500 hover:text-gray-800 hover:bg-gray-100 rounded-full transition-all"
                title="列印預覽"
              >
                <Printer size={20} />
              </button>
              <button 
                onClick={handleLogout}
                className="flex items-center gap-1 bg-gray-100 hover:bg-gray-200 text-gray-700 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors"
              >
                <LogOut size={16} /> 登出
              </button>
            </div>
          </div>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

        {/* Calendar Section */}
        <section>
          <Calendar 
            currentDate={currentDate}
            data={data!}
            currentUser={currentUser}
            onMonthChange={(inc) => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + inc, 1))}
            onDateClick={handleDateClick}
          />
        </section>

        {/* Admin Section */}
        {currentUser.role === UserRole.ADMIN && (
          <section>
            <h2 className="text-xl font-bold text-gray-800 mb-4">後台管理</h2>
            <AdminPanel 
              data={data!} 
              onUpdateUser={handleUserUpdate}
              onUpdateSettings={handleSettingsUpdate}
            />
          </section>
        )}
      </main>

      {/* Admin Shift Selection Modal */}
      {selectedAdminDate && data && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="bg-gray-50 px-6 py-4 border-b border-gray-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-gray-800">排班管理: {selectedAdminDate}</h3>
              <button onClick={() => setSelectedAdminDate(null)} className="text-gray-400 hover:text-gray-600"><LogOut size={18} className="rotate-180" /></button>
            </div>

            <div className="p-6 space-y-4">
              <div className="text-sm text-gray-500 mb-2">選擇當日上班人員：</div>

              {/* Option: Confirmed/Signups */}
              <div className="space-y-2 max-h-60 overflow-y-auto">
                {(data.shifts[selectedAdminDate]?.signups || []).length === 0 && (
                   <div className="text-gray-400 text-center italic py-2">無人報名</div>
                )}

                {(data.shifts[selectedAdminDate]?.signups || []).map(uid => {
                  const u = data.users.find(usr => usr.id === uid);
                  if(!u) return null;
                  const isConfirmed = data.shifts[selectedAdminDate]?.confirmedUserId === uid;
                  return (
                    <button
                      key={uid}
                      onClick={() => handleAdminShiftAction('confirm', uid)}
                      className={`w-full flex items-center justify-between p-3 rounded-lg border text-left transition-all ${
                        isConfirmed ? 'border-green-500 bg-green-50 ring-1 ring-green-500' : 'border-gray-200 hover:border-blue-300'
                      }`}
                    >
                      <div className="flex items-center gap-2">
                        <span className={`w-3 h-3 rounded-full ${u.color.split(' ')[0]}`}></span>
                        <span className="font-bold">{u.name}</span>
                      </div>
                      {isConfirmed && <span className="text-green-600 text-sm font-bold">已指定</span>}
                    </button>
                  );
                })}
              </div>

              <hr className="border-gray-100 my-2" />

              {/* Special Actions */}
              <div className="grid grid-cols-2 gap-3">
                 <button 
                    onClick={() => handleAdminShiftAction('close')}
                    className={`p-2 rounded font-bold border ${data.shifts[selectedAdminDate]?.isClosed ? 'bg-red-600 text-white border-red-600' : 'bg-white text-red-600 border-red-200 hover:bg-red-50'}`}
                 >
                   {data.shifts[selectedAdminDate]?.isClosed ? '取消休診' : '設為休診'}
                 </button>
                 <button 
                    onClick={() => handleAdminShiftAction('clear')}
                    className="p-2 rounded font-bold bg-gray-100 text-gray-600 hover:bg-gray-200"
                 >
                   清除指定
                 </button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState } from 'react';
