    e.preventDefault();
    setError('');

    if (role === UserRole.ADMIN) {
      // Admin Login
      // Default to 'admin' if setting hasn't loaded yet or is empty
      const targetPass = adminPassword || 'admin';
      if (password === targetPass) {
        onLogin({
          id: 'admin',
          name: '系統管理員',
          color: 'bg-purple-100 text-purple-800',
          role: UserRole.ADMIN
        });
