                role === UserRole.STUDENT ? 'bg-white shadow text-blue-600' : 'text-gray-500'
              }`}
            >
              <UserCircle size={18} /> 工讀生
            </button>
            <button
              onClick={() => { setRole(UserRole.ADMIN); setError(''); setPassword(''); }}
              className={`flex-1 py-2 rounded-md text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                role === UserRole.ADMIN ? 'bg-white shadow text-blue-600' : 'text-gray-500'
              }`}
            >
              <ShieldCheck size={18} /> 管理員
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
