import { GAS_API_URL, TAIWAN_HOLIDAYS_2026_2027 } from '../constants';
import { AppData, ApiPayload, UserRole } from '../types';

// Mock data for initial load if API fails or is empty (for demonstration stability)
const MOCK_DATA: AppData = {
  users: [
    { id: 'u1', name: '王小明', color: 'bg-blue-100 text-blue-800', role: UserRole.STUDENT },
    { id: 'u2', name: '李大華', color: 'bg-green-100 text-green-800', role: UserRole.STUDENT },
    { id: 'u3', name: '張小美', color: 'bg-pink-100 text-pink-800', role: UserRole.STUDENT },
  ],
  shifts: {},
  settings: {
    holidays: TAIWAN_HOLIDAYS_2026_2027, 
    adminPassword: 'admin',
  },
};

export const fetchAppData = async (): Promise<AppData> => {
  try {
    // GAS often uses GET for retrieving data to avoid CORS preflight issues on simple requests
    const response = await fetch(`${GAS_API_URL}?action=getData`);
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    const data = await response.json();

    // Robustness: ensure basic structure exists
    if (!data.users || !data.shifts) {
      console.warn("API returned incomplete data, using mock/partial data", data);
      return { ...MOCK_DATA, ...data };
    }
    return data;
  } catch (error) {
    console.error("Failed to fetch data from GAS:", error);
    // Fallback for demo purposes if the user's specific URL isn't configured with the right backend script yet
    console.warn("Falling back to local mock data.");
    return MOCK_DATA;
  }
};

export const sendAction = async (payload: ApiPayload): Promise<AppData | null> => {
  try {
    // Using POST for actions. 
    // Note: Google Apps Script Web App must implement doPost(e) and return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
    // And handle CORS headers appropriately.

    // For many GAS implementations, avoiding CORS preflight via text/plain is a common hack, 
    // but we will try standard JSON first.
    const response = await fetch(GAS_API_URL, {
      method: 'POST',
      // Using text/plain to prevent CORS preflight OPTIONS request which GAS doesn't handle natively without workarounds
      headers: {
        'Content-Type': 'text/plain;charset=utf-8', 
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      throw new Error(`Server error: ${response.status}`);
    }

    const result = await response.json();
    return result; // Expecting the updated full dataset back to sync state
  } catch (error) {
    console.error("Action failed:", error);
    return null;
  }
};

