      if (!user) {
        setError('請選擇姓名 (｡•́︿•̀｡)');
        return;
      }
      if (user.password && user.password !== password) {
        setError('密碼錯誤 (｡•́︿•̀｡)');
        return;
      }
      onLogin(user);
