          </div>
          <h1 className="text-3xl font-bold text-gray-800 mb-1 tracking-tight">放射科排班系統</h1>
          <p className="text-gray-500 text-sm">RadioShift • 輕鬆管理你的班表</p>
        </div>

        <div className="px-8 pb-10">
          <div className="flex bg-gray-100/50 p-1.5 rounded-2xl mb-8 border border-gray-200">
            <button
              onClick={() => { setRole(UserRole.STUDENT); setError(''); setPassword(''); }}
