import React from 'react';
import { AppData } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';
import { X, Printer } from 'lucide-react';

interface PrintViewProps {
  currentDate: Date;
  data: AppData;
  onClose: () => void;
}

const PrintView: React.FC<PrintViewProps> = ({ currentDate, data, onClose }) => {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const weeks = [];
  let currentWeek = new Array(7).fill(null);
  for (let i = 0; i < firstDayOfMonth; i++) currentWeek[i] = null;

  for (let d = 1; d <= daysInMonth; d++) {
    const dayOfWeek = new Date(year, month, d).getDay();
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const shift = data.shifts[dateStr];

    let content = DEFAULT_WORKER_NAME;
    let isSpecial = false;

    if (shift?.isClosed) {
        content = "休診";
        isSpecial = true;
    } else if (shift?.confirmedUserId) {
      const u = data.users.find(user => user.id === shift.confirmedUserId);
      if (u) content = u.name;
    } else if (shift?.signups && shift.signups.length > 1) {
      content = ""; // Print view should probably be clean, leave blank if undecided? Or show "待定"
      content = "待定";
    }

    currentWeek[dayOfWeek] = { day: d, content, isSpecial };

    if (dayOfWeek === 6 || d === daysInMonth) {
      weeks.push(currentWeek);
      currentWeek = new Array(7).fill(null);
    }
  }

  return (
    <div className="fixed inset-0 bg-gray-900/50 backdrop-blur-sm z-50 overflow-auto flex items-center justify-center">
      <div className="bg-white w-full max-w-5xl min-h-screen md:min-h-0 md:h-auto md:max-h-[90vh] md:rounded-3xl shadow-2xl overflow-hidden flex flex-col">

        {/* Toolbar */}
        <div className="bg-gray-800 text-white p-4 flex justify-between items-center no-print shrink-0">
           <h1 className="text-xl font-bold flex items-center gap-2">
             <Printer size={20} className="text-blue-300"/> 列印預覽模式
           </h1>
           <div className="flex gap-3">
             <button onClick={() => window.print()} className="bg-blue-500 hover:bg-blue-600 text-white px-6 py-2 rounded-full font-bold transition-all shadow-lg hover:shadow-blue-500/50">
               立即列印
             </button>
             <button onClick={onClose} className="bg-gray-700 hover:bg-gray-600 text-white p-2 rounded-full transition-all">
               <X size={20} />
             </button>
           </div>
        </div>

        {/* Printable Area */}
        <div className="p-8 md:p-12 overflow-auto bg-white flex-1">
          <div className="print-container max-w-4xl mx-auto">
            {/* Print Header */}
            <div className="text-center mb-8">
               <h2 className="text-4xl font-extrabold text-gray-900 mb-2">{year} 年 {month + 1} 月 放射科值班表</h2>
               <div className="h-1.5 w-32 bg-gradient-to-r from-blue-500 to-teal-400 mx-auto rounded-full"></div>
            </div>

            <table className="w-full border-collapse border border-gray-300 shadow-sm rounded-lg overflow-hidden">
              <thead>
                <tr className="bg-gray-100">
                  {WEEKDAYS.map((d, i) => (
                    <th key={d} className={`border border-gray-300 p-3 w-[14.28%] text-center font-bold text-lg ${
                        i===0 ? 'text-red-600 bg-red-50' : i===6 ? 'text-green-600 bg-green-50' : 'text-gray-700'
                    }`}>
                        週{d}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {weeks.map((week, idx) => (
                  <tr key={idx}>
                    {week.map((cell: any, cIdx: number) => {
                      if (!cell) return <td key={cIdx} className="border border-gray-300 p-4 h-32 bg-gray-50/30"></td>;

                      const isWeekend = cIdx === 0 || cIdx === 6;
                      return (
                        <td key={cIdx} className={`border border-gray-300 p-2 h-32 align-top relative ${isWeekend ? 'bg-gray-50/50' : ''}`}>
                          <span className={`font-bold text-xl block mb-2 px-2 ${cIdx === 0 ? 'text-red-500' : cIdx===6 ? 'text-green-600' : 'text-gray-800'}`}>
                              {cell.day}
                          </span>
                          <div className="flex justify-center items-center h-16">
                             {cell.content === "休診" ? (
                                 <span className="text-gray-400 font-bold text-xl border-2 border-gray-300 rounded-lg px-4 py-1 rotate-12 opacity-50">休診</span>
                             ) : (
                                 <span className={`text-xl font-bold px-3 py-1 rounded ${cell.content === '待定' ? 'text-yellow-600 bg-yellow-50' : 'text-blue-900'}`}>
                                     {cell.content}
                                 </span>
                             )}
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="mt-8 flex justify-between text-sm text-gray-500 px-2">
                <span>製表日期：{new Date().toLocaleDateString()}</span>
                <span>放射科辦公室 確認</span>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @media print {
            body * {
                visibility: hidden;
            }
            .print-container, .print-container * {
                visibility: visible;
            }
            .print-container {
                position: absolute;
                left: 0;
                top: 0;
                width: 100%;
            }
            /* Ensure colors print */
            * {
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
            }
        }
      `}</style>
    </div>
  );
};

export default PrintView;

import React, { useState, useEffect } from 'react';
import { User, AppData, UserRole } from './types';
import { fetchAppData, sendAction } from './services/api';
import Login from './components/Login';
import Calendar from './components/Calendar';
import AdminPanel from './components/AdminPanel';
import PrintView from './components/PrintView';
import { LogOut, Printer, RefreshCw, UserCheck, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [data, setData] = useState<AppData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [syncing, setSyncing] = useState<boolean>(false);
  const [currentDate, setCurrentDate] = useState<Date>(new Date());
  const [showPrintView, setShowPrintView] = useState(false);

  const [selectedAdminDate, setSelectedAdminDate] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setLoading(false);
  };

  const handleSync = async () => {
    setSyncing(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setSyncing(false);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setSelectedAdminDate(null);
  };

  const handleDateClick = async (dateStr: string) => {
    if (!currentUser || !data) return;

    if (currentUser.role === UserRole.STUDENT) {
      const shift = data.shifts[dateStr];
      if (shift?.isClosed || shift?.confirmedUserId) return; 

      const currentSignups = shift?.signups || [];
      const isSignedUp = currentSignups.includes(currentUser.id);

      const newSignups = isSignedUp 
        ? currentSignups.filter(id => id !== currentUser.id)
        : [...currentSignups, currentUser.id];

      const newData = { ...data, shifts: { ...data.shifts, [dateStr]: { ...shift, date: dateStr, signups: newSignups } } };
      setData(newData);

      await sendAction({
        action: 'toggleSignup',
        payload: { date: dateStr, userId: currentUser.id }
      });
    } else if (currentUser.role === UserRole.ADMIN) {
      setSelectedAdminDate(dateStr);
    }
  };

  const handleAdminShiftAction = async (action: 'confirm' | 'close' | 'clear', targetUserId?: string) => {
    if (!selectedAdminDate || !data) return;

    const shift = data.shifts[selectedAdminDate] || { date: selectedAdminDate, signups: [] };
    let newShift = { ...shift };

    if (action === 'confirm' && targetUserId) {
      newShift.confirmedUserId = targetUserId;
      newShift.isClosed = false;
    } else if (action === 'close') {
      newShift.isClosed = !newShift.isClosed;
      newShift.confirmedUserId = undefined;
    } else if (action === 'clear') {
      newShift.confirmedUserId = undefined;
      newShift.isClosed = false;
    }

    const newData = { ...data, shifts: { ...data.shifts, [selectedAdminDate]: newShift } };
    setData(newData);
    setSelectedAdminDate(null);

    await sendAction({
      action: 'assignShift',
      payload: { date: selectedAdminDate, ...newShift }
    });
  };

  const handleUserUpdate = async (action: 'add' | 'delete', user?: User) => {
    if (!data) return;
    let newUsers = [...data.users];

    if (action === 'add' && user) {
      newUsers.push(user);
    } else if (action === 'delete' && user) {
      newUsers = newUsers.filter(u => String(u.id) !== String(user.id));
    }

    setData({ ...data, users: newUsers });

    await sendAction({
      action: 'manageUser',
      payload: { type: action, user }
    });
  };

  const handleSettingsUpdate = async (newSettings: AppData['settings']) => {
    if (!data) return;
    setData({ ...data, settings: newSettings });

    await sendAction({
      action: 'updateSettings',
      payload: newSettings
    });
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-pink-50">
        <div className="animate-bounce bg-white p-4 rounded-full shadow-lg mb-4">
           <UserCheck size={32} className="text-pink-500" />
        </div>
        <p className="text-gray-500 font-bold animate-pulse">正在為您準備班表...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={data?.users || []} adminPassword={data?.settings.adminPassword} onLogin={handleLogin} />;
  }

  if (showPrintView && data) {
    return <PrintView currentDate={currentDate} data={data} onClose={() => setShowPrintView(false)} />;
  }

  return (
    <div className="min-h-screen pb-12 transition-colors duration-500">
      {/* Top Navbar */}
      <nav className="bg-white/80 backdrop-blur-md border-b border-gray-100 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white shadow-lg ${currentUser.role === UserRole.ADMIN ? 'bg-gradient-to-br from-purple-500 to-indigo-500' : 'bg-gradient-to-br from-blue-400 to-cyan-400'}`}>
                 <span className="font-bold text-lg">{currentUser.name[0]}</span>
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-gray-800 text-lg leading-tight">
                  {currentUser.name}
                </span>
                <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">
                  {currentUser.role === UserRole.ADMIN ? 'Administrator' : 'Student'}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleSync}
                disabled={syncing}
                className={`p-3 rounded-xl transition-all ${syncing ? 'animate-spin text-blue-400' : 'text-gray-400 hover:text-blue-500 hover:bg-blue-50'}`}
                title="同步資料"
              >
                <RefreshCw size={20} />
              </button>
              <button 
                onClick={() => setShowPrintView(true)}
                className="hidden md:flex items-center gap-2 bg-gray-100 hover:bg-gray-800 hover:text-white text-gray-600 px-4 py-2 rounded-xl font-bold transition-all"
              >
                <Printer size={18} /> 列印預覽
              </button>
              <button 
                onClick={handleLogout}
                className="flex items-center gap-2 bg-red-50 hover:bg-red-500 hover:text-white text-red-500 px-4 py-2 rounded-xl font-bold transition-all"
              >
                <LogOut size={18} /> <span className="hidden sm:inline">登出</span>
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-10">
        <section>
          <Calendar 
            currentDate={currentDate}
            data={data!}
            currentUser={currentUser}
            onMonthChange={(inc) => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + inc, 1))}
            onDateClick={handleDateClick}
          />
        </section>

        {currentUser.role === UserRole.ADMIN && (
          <section>
            <div className="flex items-center gap-2 mb-6 ml-2">
                <div className="h-8 w-1.5 bg-gradient-to-b from-blue-500 to-purple-500 rounded-full"></div>
                <h2 className="text-2xl font-bold text-gray-800">後台管理中心</h2>
            </div>
            <AdminPanel 
              data={data!} 
              onUpdateUser={handleUserUpdate}
              onUpdateSettings={handleSettingsUpdate}
            />
          </section>
        )}
      </main>

      {/* Admin Shift Management Modal */}
      {selectedAdminDate && data && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden transform scale-100 transition-all">
            <div className="bg-gradient-to-r from-gray-800 to-gray-700 p-6 text-white flex justify-between items-center">
              <div>
                 <h3 className="text-xl font-bold">排班模擬</h3>
                 <p className="text-gray-300 text-sm opacity-80">{selectedAdminDate}</p>
              </div>
              <button onClick={() => setSelectedAdminDate(null)} className="text-white/60 hover:text-white bg-white/10 hover:bg-white/20 p-2 rounded-full transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 space-y-6">
              <div>
                  <h4 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-3">報名人員</h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto pr-1 custom-scrollbar">
                    {(data.shifts[selectedAdminDate]?.signups || []).length === 0 && (
                      <div className="text-center py-6 bg-gray-50 rounded-xl border border-dashed border-gray-200 text-gray-400">
                         尚無人報名
                      </div>
                    )}

                    {(data.shifts[selectedAdminDate]?.signups || []).map(uid => {
                      const u = data.users.find(usr => usr.id === uid);
                      if(!u) return null;
                      const isConfirmed = data.shifts[selectedAdminDate]?.confirmedUserId === uid;
                      return (
                        <button
                          key={uid}
                          onClick={() => handleAdminShiftAction('confirm', uid)}
                          className={`w-full flex items-center justify-between p-3 rounded-xl border-2 transition-all group ${
                            isConfirmed 
                              ? 'border-green-500 bg-green-50 shadow-sm' 
                              : 'border-transparent bg-gray-50 hover:bg-blue-50 hover:border-blue-200'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <span className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold shadow-sm ${u.color}`}>
                              {u.name[0]}
                            </span>
                            <span className="font-bold text-gray-700">{u.name}</span>
                          </div>
                          {isConfirmed ? (
                             <span className="text-green-600 text-xs font-bold bg-green-100 px-2 py-1 rounded-full">Formal</span>
                          ) : (
                             <span className="text-gray-300 group-hover:text-blue-400 text-xs font-bold">Assign</span>
                          )}
                        </button>
                      );
                    })}
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-3 pt-4 border-t border-gray-100">
                 <button 
                    onClick={() => handleAdminShiftAction('close')}
                    className={`p-3 rounded-xl font-bold border-2 transition-all ${
                      data.shifts[selectedAdminDate]?.isClosed 
                      ? 'bg-red-500 text-white border-red-500 shadow-lg shadow-red-200' 
                      : 'bg-white text-red-500 border-red-100 hover:border-red-300 hover:bg-red-50'
                    }`}
                 >
                   {data.shifts[selectedAdminDate]?.isClosed ? '🔓 解除休診' : '🔒 設為休診'}
                 </button>
                 <button 
                    onClick={() => handleAdminShiftAction('clear')}
                    className="p-3 rounded-xl font-bold bg-gray-100 text-gray-600 hover:bg-gray-200 border-2 border-transparent"
                 >
                   清除指定
                 </button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AppData, User, UserRole } from '../types';
import { BarChart3, Trophy } from 'lucide-react';

interface StatsSidebarProps {
  currentDate: Date;
  data: AppData;
}

const StatsSidebar: React.FC<StatsSidebarProps> = ({ currentDate, data }) => {
  const students = data.users.filter(u => u.role === UserRole.STUDENT);
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  // Calculate stats for the current month
  const stats = useMemo(() => {
    const counts: Record<string, number> = {};
    const currentMonthPrefix = `${year}-${String(month + 1).padStart(2, '0')}`;

    // Initialize 0
    students.forEach(s => counts[s.id] = 0);

    // Count confirmed shifts
    Object.values(data.shifts).forEach(shift => {
      if (shift.date.startsWith(currentMonthPrefix) && shift.confirmedUserId) {
        counts[shift.confirmedUserId] = (counts[shift.confirmedUserId] || 0) + 1;
      }
    });

    // Sort by count descending
    return students
      .map(s => ({ user: s, count: counts[s.id] || 0 }))
      .sort((a, b) => b.count - a.count);
  }, [data.shifts, students, year, month]);

  const totalShifts = stats.reduce((acc, curr) => acc + curr.count, 0);

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-gray-100 p-6 sticky top-24">
      <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
        <div className="p-2.5 bg-orange-100 text-orange-500 rounded-xl">
          <BarChart3 size={20} />
        </div>
        <div>
          <h3 className="font-bold text-gray-800 text-lg">{month + 1}月 排班統計</h3>
          <p className="text-xs text-gray-400 font-bold">Total: {totalShifts} 班</p>
        </div>
      </div>

      <div className="space-y-3">
        {stats.map((item, index) => (
          <div key={item.user.id} className="group flex items-center justify-between p-3 rounded-2xl hover:bg-gray-50 transition-colors border border-transparent hover:border-gray-100">
            <div className="flex items-center gap-3">
              <div className="relative">
                <span className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold shadow-sm text-gray-700 ${item.user.color.replace('bg-', 'bg-opacity-50 bg-')}`}>
                  {item.user.name[0]}
                </span>
                {index === 0 && item.count > 0 && (
                  <div className="absolute -top-1 -right-1 bg-yellow-400 text-white rounded-full p-0.5 border-2 border-white shadow-sm">
                    <Trophy size={10} />
                  </div>
                )}
              </div>
              <span className="font-bold text-gray-700 group-hover:text-blue-600 transition-colors">
                {item.user.name}
              </span>
            </div>

            <div className="flex items-center gap-2">
              <div className="h-2 w-16 bg-gray-100 rounded-full overflow-hidden hidden xl:block">
                <div 
                  className={`h-full rounded-full ${item.user.color.split(' ')[0]}`} 
                  style={{ width: `${totalShifts > 0 ? (item.count / totalShifts) * 100 : 0}%` }}
                ></div>
              </div>
              <span className={`text-sm font-bold px-2.5 py-1 rounded-lg ${item.count > 0 ? 'bg-gray-800 text-white' : 'bg-gray-100 text-gray-400'}`}>
                {item.count}
              </span>
            </div>
          </div>
        ))}

        {students.length === 0 && (
          <div className="text-center text-gray-400 py-4 text-sm">
            無工讀生資料
          </div>
        )}
      </div>
    </div>
  );
};

export default StatsSidebar;

import React from 'react';
import { AppData } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';
import { X, Printer, FileDown } from 'lucide-react';

interface PrintViewProps {
  currentDate: Date;
  data: AppData;
  onClose: () => void;
}

const PrintView: React.FC<PrintViewProps> = ({ currentDate, data, onClose }) => {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const weeks = [];
  let currentWeek = new Array(7).fill(null);
  for (let i = 0; i < firstDayOfMonth; i++) currentWeek[i] = null;

  for (let d = 1; d <= daysInMonth; d++) {
    const dayOfWeek = new Date(year, month, d).getDay();
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const shift = data.shifts[dateStr];

    let content = DEFAULT_WORKER_NAME;
    let isSpecial = false;

    if (shift?.isClosed) {
        content = "休診";
        isSpecial = true;
    } else if (shift?.confirmedUserId) {
      const u = data.users.find(user => user.id === shift.confirmedUserId);
      if (u) content = u.name;
    } else if (shift?.signups && shift.signups.length > 1) {
      content = "待定";
    }

    currentWeek[dayOfWeek] = { day: d, content, isSpecial };

    if (dayOfWeek === 6 || d === daysInMonth) {
      weeks.push(currentWeek);
      currentWeek = new Array(7).fill(null);
    }
  }

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 bg-gray-900/50 backdrop-blur-sm z-50 overflow-auto flex items-center justify-center">
      <div className="bg-white w-full max-w-5xl min-h-screen md:min-h-0 md:h-auto md:max-h-[90vh] md:rounded-3xl shadow-2xl overflow-hidden flex flex-col">

        {/* Toolbar */}
        <div className="bg-gray-800 text-white p-4 flex justify-between items-center no-print shrink-0">
           <h1 className="text-xl font-bold flex items-center gap-2">
             <Printer size={20} className="text-blue-300"/> 列印預覽 / 匯出
           </h1>
           <div className="flex gap-3">
             <button 
                onClick={handlePrint} 
                className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-xl font-bold transition-all shadow-lg flex items-center gap-2"
                title="系統將開啟列印視窗，請選擇「另存為 PDF」"
             >
               <FileDown size={18} /> 匯出 PDF
             </button>
             <button 
                onClick={handlePrint} 
                className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-xl font-bold transition-all shadow-lg flex items-center gap-2"
             >
               <Printer size={18} /> 列印
             </button>
             <button onClick={onClose} className="bg-gray-700 hover:bg-gray-600 text-white p-2 rounded-full transition-all">
               <X size={20} />
             </button>
           </div>
        </div>

        {/* Printable Area */}
        <div className="p-8 md:p-12 overflow-auto bg-white flex-1">
          <div className="print-container max-w-4xl mx-auto">
            {/* Print Header */}
            <div className="text-center mb-8">
               <h2 className="text-4xl font-extrabold text-gray-900 mb-2">{year} 年 {month + 1} 月 放射科值班表</h2>
               <div className="h-1.5 w-32 bg-gradient-to-r from-blue-500 to-teal-400 mx-auto rounded-full"></div>
            </div>

            <table className="w-full border-collapse border border-gray-300 shadow-sm rounded-lg overflow-hidden">
              <thead>
                <tr className="bg-gray-100">
                  {WEEKDAYS.map((d, i) => (
                    <th key={d} className={`border border-gray-300 p-3 w-[14.28%] text-center font-bold text-lg ${
                        i===0 ? 'text-red-600 bg-red-50' : i===6 ? 'text-green-600 bg-green-50' : 'text-gray-700'
                    }`}>
                        週{d}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {weeks.map((week, idx) => (
                  <tr key={idx}>
                    {week.map((cell: any, cIdx: number) => {
                      if (!cell) return <td key={cIdx} className="border border-gray-300 p-4 h-32 bg-gray-50/30"></td>;

                      const isWeekend = cIdx === 0 || cIdx === 6;
                      return (
                        <td key={cIdx} className={`border border-gray-300 p-2 h-32 align-top relative ${isWeekend ? 'bg-gray-50/50' : ''}`}>
                          <span className={`font-bold text-xl block mb-2 px-2 ${cIdx === 0 ? 'text-red-500' : cIdx===6 ? 'text-green-600' : 'text-gray-800'}`}>
                              {cell.day}
                          </span>
                          <div className="flex justify-center items-center h-16">
                             {cell.content === "休診" ? (
                                 <span className="text-gray-400 font-bold text-xl border-2 border-gray-300 rounded-lg px-4 py-1 rotate-12 opacity-50">休診</span>
                             ) : (
                                 <span className={`text-xl font-bold px-3 py-1 rounded ${cell.content === '待定' ? 'text-yellow-600 bg-yellow-50' : 'text-blue-900'}`}>
                                     {cell.content}
                                 </span>
                             )}
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="mt-8 flex justify-between text-sm text-gray-500 px-2">
                <span>製表日期：{new Date().toLocaleDateString()}</span>
                <span>放射科辦公室 確認</span>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @media print {
            body * {
                visibility: hidden;
            }
            .print-container, .print-container * {
                visibility: visible;
            }
            .print-container {
                position: absolute;
                left: 0;
                top: 0;
                width: 100%;
            }
            /* Ensure colors print */
            * {
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
            }
        }
      `}</style>
    </div>
  );
};

export default PrintView;

import React, { useState, useEffect } from 'react';
import { User, AppData, UserRole } from './types';
import { fetchAppData, sendAction } from './services/api';
import Login from './components/Login';
import Calendar from './components/Calendar';
import AdminPanel from './components/AdminPanel';
import PrintView from './components/PrintView';
import StatsSidebar from './components/StatsSidebar';
import { LogOut, Printer, RefreshCw, UserCheck, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [data, setData] = useState<AppData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [syncing, setSyncing] = useState<boolean>(false);
  const [currentDate, setCurrentDate] = useState<Date>(new Date());
  const [showPrintView, setShowPrintView] = useState(false);

  const [selectedAdminDate, setSelectedAdminDate] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setLoading(false);
  };

  const handleSync = async () => {
    setSyncing(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setSyncing(false);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setSelectedAdminDate(null);
  };

  const handleDateClick = async (dateStr: string) => {
    if (!currentUser || !data) return;

    if (currentUser.role === UserRole.STUDENT) {
      const shift = data.shifts[dateStr];
      if (shift?.isClosed || shift?.confirmedUserId) return; 

      const currentSignups = shift?.signups || [];
      const isSignedUp = currentSignups.includes(currentUser.id);

      const newSignups = isSignedUp 
        ? currentSignups.filter(id => id !== currentUser.id)
        : [...currentSignups, currentUser.id];

      const newData = { ...data, shifts: { ...data.shifts, [dateStr]: { ...shift, date: dateStr, signups: newSignups } } };
      setData(newData);

      await sendAction({
        action: 'toggleSignup',
        payload: { date: dateStr, userId: currentUser.id }
      });
    } else if (currentUser.role === UserRole.ADMIN) {
      setSelectedAdminDate(dateStr);
    }
  };

  const handleAdminShiftAction = async (action: 'confirm' | 'close' | 'clear', targetUserId?: string) => {
    if (!selectedAdminDate || !data) return;

    const shift = data.shifts[selectedAdminDate] || { date: selectedAdminDate, signups: [] };
    let newShift = { ...shift };

    if (action === 'confirm' && targetUserId) {
      newShift.confirmedUserId = targetUserId;
      newShift.isClosed = false;
    } else if (action === 'close') {
      newShift.isClosed = !newShift.isClosed;
      newShift.confirmedUserId = undefined;
    } else if (action === 'clear') {
      newShift.confirmedUserId = undefined;
      newShift.isClosed = false;
    }

    const newData = { ...data, shifts: { ...data.shifts, [selectedAdminDate]: newShift } };
    setData(newData);
    setSelectedAdminDate(null);

    await sendAction({
      action: 'assignShift',
      payload: { date: selectedAdminDate, ...newShift }
    });
  };

  const handleUserUpdate = async (action: 'add' | 'delete', user?: User) => {
    if (!data) return;
    let newUsers = [...data.users];

    if (action === 'add' && user) {
      newUsers.push(user);
    } else if (action === 'delete' && user) {
      newUsers = newUsers.filter(u => String(u.id) !== String(user.id));
    }

    setData({ ...data, users: newUsers });

    await sendAction({
      action: 'manageUser',
      payload: { type: action, user }
    });
  };

  const handleSettingsUpdate = async (newSettings: AppData['settings']) => {
    if (!data) return;
    setData({ ...data, settings: newSettings });

    await sendAction({
      action: 'updateSettings',
      payload: newSettings
    });
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-pink-50">
        <div className="animate-bounce bg-white p-4 rounded-full shadow-lg mb-4">
           <UserCheck size={32} className="text-pink-500" />
        </div>
        <p className="text-gray-500 font-bold animate-pulse">正在為您準備班表...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={data?.users || []} adminPassword={data?.settings.adminPassword} onLogin={handleLogin} />;
  }

  if (showPrintView && data) {
    return <PrintView currentDate={currentDate} data={data} onClose={() => setShowPrintView(false)} />;
  }

  return (
    <div className="min-h-screen pb-12 transition-colors duration-500">
      {/* Top Navbar */}
      <nav className="bg-white/80 backdrop-blur-md border-b border-gray-100 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white shadow-lg ${currentUser.role === UserRole.ADMIN ? 'bg-gradient-to-br from-purple-500 to-indigo-500' : 'bg-gradient-to-br from-blue-400 to-cyan-400'}`}>
                 <span className="font-bold text-lg">{currentUser.name[0]}</span>
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-gray-800 text-lg leading-tight">
                  {currentUser.name}
                </span>
                <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">
                  {currentUser.role === UserRole.ADMIN ? 'Administrator' : 'Student'}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleSync}
                disabled={syncing}
