import { GAS_API_URL, TAIWAN_HOLIDAYS_2026_2027 } from '../constants';
import { AppData, ApiPayload, UserRole } from '../types';

// Mock data for initial load if API fails or is empty (for demonstration stability)
const MOCK_DATA: AppData = {
  users: [
    { id: 'u1', name: '昀儒', color: 'bg-blue-100 text-green-800', role: UserRole.STUDENT, password: '1234' },
    { id: 'u2', name: '語晨', color: 'bg-green-100 text-pink-800', role: UserRole.STUDENT, password: '4321' },
    { id: 'u3', name: '蘇蘇', color: 'bg-pink-100 text-blue-800', role: UserRole.STUDENT, password: '0000' },
  ],
  shifts: {},
  settings: {
    holidays: TAIWAN_HOLIDAYS_2026_2027, 
    adminPassword: 'admin',
  },
};

export const fetchAppData = async (): Promise<AppData> => {
  try {
    // GAS often uses GET for retrieving data to avoid CORS preflight issues on simple requests
    const response = await fetch(`${GAS_API_URL}?action=getData`);
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    const data = await response.json();

    // Robustness: ensure basic structure exists
    if (!data.users || !data.shifts) {
      console.warn("API returned incomplete data, using mock/partial data", data);
      return { ...MOCK_DATA, ...data };
    }
    return data;
  } catch (error) {
    console.error("Failed to fetch data from GAS:", error);
    // Fallback for demo purposes if the user's specific URL isn't configured with the right backend script yet
    console.warn("Falling back to local mock data.");
    return MOCK_DATA;
  }
};

export const sendAction = async (payload: ApiPayload): Promise<AppData | null> => {
  try {
    // Using POST for actions. 
    // Note: Google Apps Script Web App must implement doPost(e) and return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
    // And handle CORS headers appropriately.

    // For many GAS implementations, avoiding CORS preflight via text/plain is a common hack, 
    // but we will try standard JSON first.
    const response = await fetch(GAS_API_URL, {
      method: 'POST',
      // Using text/plain to prevent CORS preflight OPTIONS request which GAS doesn't handle natively without workarounds
      headers: {
        'Content-Type': 'text/plain;charset=utf-8', 
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      throw new Error(`Server error: ${response.status}`);
    }

    const result = await response.json();
    return result; // Expecting the updated full dataset back to sync state
  } catch (error) {
    console.error("Action failed:", error);
    return null;
  }
};

import React from 'react';
import { AppData, User, ShiftDay, UserRole } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';
import { Check, Lock, Calendar as CalendarIcon, ChevronLeft, ChevronRight } from 'lucide-react';

interface CalendarProps {
  currentDate: Date;
  data: AppData;
  currentUser: User | null;
  onMonthChange: (increment: number) => void;
  onDateClick: (dateStr: string) => void;
}

const Calendar: React.FC<CalendarProps> = ({ 
  currentDate, 
  data, 
  currentUser, 
  onMonthChange, 
  onDateClick
}) => {

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const formatDate = (y: number, m: number, d: number) => {
    return `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  };

  const getDayDetails = (day: number) => {
    const dateStr = formatDate(year, month, day);
    const dateObj = new Date(year, month, day);
    const dayOfWeek = dateObj.getDay();

    const isHoliday = data.settings.holidays.includes(dateStr);
    const isSunday = dayOfWeek === 0;
    const isSaturday = dayOfWeek === 6;

    let dateStyle = 'text-gray-600 bg-white border-gray-100'; 
    let badge = null;

    if (isSunday || isHoliday) {
      dateStyle = 'text-red-600 bg-red-50/50 border-red-100';
      badge = isHoliday ? <span className="absolute -top-2 -right-2 bg-red-400 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm z-10">假</span> : null;
    } else if (isSaturday) {
      dateStyle = 'text-green-600 bg-green-50/50 border-green-100';
    }

    const shift: ShiftDay | undefined = data.shifts[dateStr];
    const signups = shift?.signups || [];
    const confirmedId = shift?.confirmedUserId;
    const isClosed = shift?.isClosed;

    return { dateStr, day, dayOfWeek, isHoliday, isSunday, isSaturday, dateStyle, badge, signups, confirmedId, isClosed };
  };

  const renderCellContent = (details: ReturnType<typeof getDayDetails>) => {
    const { signups, confirmedId, isClosed, isSunday, isHoliday, isSaturday } = details;

    if (isClosed) {
      return (
        <div className="flex flex-col items-center justify-center flex-1 opacity-50">
          <Lock size={16} className="text-gray-400 mb-1" />
          <span className="text-gray-400 font-bold text-sm tracking-widest">休診</span>
        </div>
      );
    }

    // Time Display
    let timeText = '10:00-18:00';
    if (isSunday || isHoliday) timeText = '10:00-17:00';

    const TimeBadge = () => (
       <div className={`text-[10px] mb-1 font-medium text-center ${isSunday||isHoliday ? 'text-red-500' : isSaturday ? 'text-green-600' : 'text-gray-400'}`}>
         {timeText}
       </div>
    );

    // Logic: Confirmed user OR Single Signup (Auto-confirmed visually)
    const activeUserId = confirmedId || (signups.length === 1 ? signups[0] : null);

    if (activeUserId) {
      const user = data.users.find(u => u.id === activeUserId);
      if (user) {
        return (
          <div className="flex flex-col h-full justify-between pb-1">
            <TimeBadge />
            <div className={`py-3 px-1 rounded-xl text-base font-bold w-full text-center shadow-sm border border-white/50 ${user.color} flex flex-col items-center justify-center`}>
               <span className="truncate w-full leading-none">{user.name}</span>
            </div>
          </div>
        );
      }
    } else if (signups.length === 0) {
      return (
        <div className="flex flex-col h-full justify-between pb-1">
          <TimeBadge />
          <div className="py-2 px-1 rounded-xl text-sm font-medium w-full text-center bg-gray-100 text-gray-400 border border-gray-200 border-dashed">
            {DEFAULT_WORKER_NAME}
          </div>
        </div>
      );
    } else {
      return (
        <div className="flex flex-col h-full justify-between pb-1">
          <TimeBadge />
          <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-1 text-center">
            <div className="text-xs text-yellow-600 font-bold mb-1">{signups.length} 人報名</div>
            <div className="flex flex-wrap gap-1 justify-center h-5 overflow-hidden">
               {signups.map(uid => {
                 const u = data.users.find(usr => usr.id === uid);
                 return u ? <div key={uid} className={`w-1.5 h-1.5 rounded-full ${u.color.split(' ')[0]}`} /> : null;
               })}
            </div>
          </div>
        </div>
      );
    }
    return null;
  };

  const calendarCells = [];

  for (let i = 0; i < firstDayOfMonth; i++) {
    calendarCells.push(<div key={`empty-${i}`} className="min-h-[140px]" />);
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const details = getDayDetails(d);
    const isInteractable = currentUser?.role === UserRole.STUDENT && !details.isClosed && !details.confirmedId;
    const isAdmin = currentUser?.role === UserRole.ADMIN;
    const isSignedUp = details.signups.includes(currentUser?.id || '');

    calendarCells.push(
      <div 
        key={details.dateStr} 
        onClick={() => {
           if (isAdmin || isInteractable) onDateClick(details.dateStr);
        }}
        className={`
          relative min-h-[140px] p-2 rounded-2xl border transition-all duration-300 group
          flex flex-col
          ${details.dateStyle}
          ${isInteractable ? 'cursor-pointer hover:-translate-y-1 hover:shadow-lg' : ''}
          ${isAdmin ? 'cursor-pointer hover:border-blue-300 hover:shadow-md' : ''}
          ${isSignedUp && !isAdmin ? 'ring-2 ring-blue-300 bg-blue-50/80' : ''}
          ${!isInteractable && !isAdmin ? 'opacity-90' : ''}
        `}
      >
        {details.badge}

        <div className="flex justify-between items-center mb-1">
          <span className="text-xl font-bold font-quicksand">{d}</span>
          {isSignedUp && !isAdmin && <Check size={16} className="text-blue-500" strokeWidth={3} />}
          {isAdmin && details.signups.length > 0 && !details.confirmedId && (
            <div className="w-2 h-2 bg-yellow-400 rounded-full animate-pulse"></div>
          )}
        </div>

        {renderCellContent(details)}

        {/* Hover Action hint for Student */}
        {isInteractable && (
          <div className="absolute inset-0 bg-blue-500/5 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
             <span className="text-blue-600 font-bold text-xs bg-white/80 px-2 py-1 rounded-full shadow-sm">
               {isSignedUp ? '取消報名' : '點擊報名'}
             </span>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header Card */}
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 flex flex-col md:flex-row items-center justify-between gap-4">
         <div className="flex items-center gap-4">
           <div className="p-3 bg-blue-100 text-blue-600 rounded-2xl">
             <CalendarIcon size={24} />
           </div>
           <div>
             <h2 className="text-3xl font-bold text-gray-800 tracking-tight font-quicksand">
               {year} <span className="text-gray-300">/</span> {String(month + 1).padStart(2, '0')}
             </h2>
             <p className="text-gray-400 text-sm font-medium">Monthly Schedule</p>
           </div>
         </div>

         <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-2xl">
           <button onClick={() => onMonthChange(-1)} className="p-3 hover:bg-white hover:shadow-md rounded-xl transition-all text-gray-600">
             <ChevronLeft size={20} />
           </button>
           <div className="h-6 w-px bg-gray-200 mx-2"></div>
           <button onClick={() => onMonthChange(1)} className="p-3 hover:bg-white hover:shadow-md rounded-xl transition-all text-gray-600">
             <ChevronRight size={20} />
           </button>
         </div>
      </div>

      {/* Grid */}
      <div className="bg-white rounded-3xl shadow-xl border border-gray-100 p-4 md:p-6">
        <div className="grid grid-cols-7 mb-4">
          {WEEKDAYS.map((day, idx) => (
            <div key={day} className={`text-center font-bold text-sm pb-2 border-b-2 border-transparent ${
              idx === 0 ? 'text-red-400' : idx === 6 ? 'text-green-500' : 'text-gray-400'
            }`}>
              {day}
            </div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-2 md:gap-3">
          {calendarCells}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React from 'react';
import { AppData, User } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';
import { X, Printer, FileDown } from 'lucide-react';

interface PrintViewProps {
  currentDate: Date;
  data: AppData;
  onClose: () => void;
}

const PrintView: React.FC<PrintViewProps> = ({ currentDate, data, onClose }) => {
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const weeks = [];
  let currentWeek = new Array(7).fill(null);
  for (let i = 0; i < firstDayOfMonth; i++) currentWeek[i] = null;

  for (let d = 1; d <= daysInMonth; d++) {
    const dayOfWeek = new Date(year, month, d).getDay();
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const shift = data.shifts[dateStr];

    let content: React.ReactNode = DEFAULT_WORKER_NAME;
    let isSpecial = false;
    let cellStyle = "text-gray-400"; // default for no worker

    if (shift?.isClosed) {
        content = "休診";
        isSpecial = true;
        cellStyle = "text-gray-400 opacity-50";
    } else {
        // Logic: Confirmed OR Single Signup
        const activeUserId = shift?.confirmedUserId || (shift?.signups?.length === 1 ? shift.signups[0] : null);

        if (activeUserId) {
            const u = data.users.find(user => user.id === activeUserId);
            if (u) {
                content = u.name;
                cellStyle = u.color; // e.g., 'bg-blue-100 text-blue-800'
            }
        } else if (shift?.signups && shift.signups.length > 1) {
            content = "待定";
            cellStyle = "bg-yellow-100 text-yellow-800";
        }
    }

    currentWeek[dayOfWeek] = { day: d, content, isSpecial, cellStyle };

    if (dayOfWeek === 6 || d === daysInMonth) {
      weeks.push(currentWeek);
      currentWeek = new Array(7).fill(null);
    }
  }

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="fixed inset-0 bg-gray-900/50 backdrop-blur-sm z-50 overflow-auto flex items-center justify-center">
      <div className="bg-white w-full max-w-5xl min-h-screen md:min-h-0 md:h-auto md:max-h-[95vh] md:rounded-3xl shadow-2xl overflow-hidden flex flex-col">

        {/* Toolbar */}
        <div className="bg-gray-800 text-white p-4 flex justify-between items-center no-print shrink-0">
           <h1 className="text-xl font-bold flex items-center gap-2">
             <Printer size={20} className="text-blue-300"/> 列印預覽 / 匯出
           </h1>
           <div className="flex gap-3">
             <button 
                onClick={handlePrint} 
                className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-xl font-bold transition-all shadow-lg flex items-center gap-2"
                title="系統將開啟列印視窗，請選擇「另存為 PDF」"
             >
               <FileDown size={18} /> 匯出 PDF
             </button>
             <button 
                onClick={handlePrint} 
                className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-xl font-bold transition-all shadow-lg flex items-center gap-2"
             >
               <Printer size={18} /> 列印
             </button>
             <button onClick={onClose} className="bg-gray-700 hover:bg-gray-600 text-white p-2 rounded-full transition-all">
               <X size={20} />
             </button>
           </div>
        </div>

        {/* Printable Area */}
        <div className="p-4 md:p-8 overflow-auto bg-white flex-1 flex flex-col items-center">
          <div className="print-container w-full max-w-4xl mx-auto">
            {/* Print Header */}
            <div className="text-center mb-4">
               <h2 className="text-3xl font-extrabold text-gray-900 mb-2">{year} 年 {month + 1} 月 放射科值班表</h2>
               <div className="h-1 w-24 bg-gray-300 mx-auto rounded-full"></div>
            </div>

            <table className="w-full border-collapse border border-gray-400 shadow-sm rounded-lg overflow-hidden table-fixed">
              <thead>
                <tr className="bg-gray-100 h-10">
                  {WEEKDAYS.map((d, i) => (
                    <th key={d} className={`border border-gray-400 p-2 text-center font-bold text-base ${
                        i===0 ? 'text-red-600 bg-red-50' : i===6 ? 'text-green-600 bg-green-50' : 'text-gray-800'
                    }`}>
                        週{d}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {weeks.map((week, idx) => (
                  <tr key={idx} className="h-24 md:h-28">
                    {week.map((cell: any, cIdx: number) => {
                      if (!cell) return <td key={cIdx} className="border border-gray-400 p-2 bg-gray-50/20"></td>;

                      const isWeekend = cIdx === 0 || cIdx === 6;
                      const isClosed = cell.content === "休診";

                      return (
                        <td key={cIdx} className={`border border-gray-400 p-1 align-top relative ${isWeekend ? 'bg-gray-50/40' : ''}`}>
                          <span className={`font-bold text-lg block mb-1 px-2 ${cIdx === 0 ? 'text-red-500' : cIdx===6 ? 'text-green-600' : 'text-gray-800'}`}>
