                                 <div className={`w-[90%] py-2 rounded-md text-center font-bold text-lg shadow-sm ${cell.cellStyle} flex items-center justify-center`}>
                                     {cell.content}
                                 </div>
                             )}
                          </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="mt-4 flex justify-between text-xs text-gray-400 px-2">
                <span>製表日期：{new Date().toLocaleDateString()}</span>
                <span>放射科辦公室 確認</span>
            </div>
          </div>
        </div>
      </div>
      <style>{`
        @media print {
            @page {
                size: landscape;
                margin: 5mm;
            }
            body {
                margin: 0;
                padding: 0;
                background: white;
            }
            /* Hide everything */
            body > * {
                display: none;
            }
            /* Show print container */
            .fixed.inset-0 {
                position: static;
                background: white;
                height: auto;
                width: 100%;
                overflow: visible;
                display: block !important;
            }
            .no-print {
                display: none !important;
            }
