                  <div className="flex justify-end">
                      <a 
                        href={dbUrlInput} 
                        target="_blank" 
                        rel="noreferrer"
                        className="inline-flex items-center gap-2 bg-white text-green-600 px-4 py-2 rounded-xl font-bold shadow-sm hover:shadow-md hover:bg-green-600 hover:text-white transition-all border border-green-200"
                      >
                        <ExternalLink size={16} /> 開啟連結
