               </div>

               <div className="flex justify-between items-end pt-4 border-t border-gray-100">
                  <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                    <Calendar size={20} className="text-pink-500" /> 國定假日設定
                  </h3>
                  <button onClick={loadDefaultHolidays} className="text-xs bg-pink-50 hover:bg-pink-100 text-pink-600 px-3 py-1.5 rounded-lg font-bold flex items-center gap-1 transition-colors">
                    <RotateCw size={12} /> 載入預設
                  </button>
               </div>
               <div className="relative">
                 <textarea 
                    value={holidayInput} 
                    onChange={e => setHolidayInput(e.target.value)}
                    className="w-full h-64 p-4 border-2 border-gray-200 rounded-3xl font-mono text-base font-medium text-gray-900 focus:ring-4 focus:ring-pink-100 focus:border-pink-300 outline-none resize-none bg-white" 
                 />
                 <div className="absolute bottom-4 right-4 text-xs font-bold text-gray-400 bg-white/80 px-2 rounded-md">YYYY-MM-DD</div>
               </div>
            </div>

            <div className="space-y-6">
              <div className="bg-purple-50 p-6 rounded-3xl border border-purple-100">
                 <h3 className="text-lg font-bold text-purple-800 mb-4 flex items-center gap-2">
                   <Lock size={20} /> 管理員密碼
                 </h3>
                 <input type="text" value={adminPassInput} onChange={e => setAdminPassInput(e.target.value)}
                  className="w-full p-4 border-none bg-white rounded-2xl shadow-sm focus:ring-2 focus:ring-purple-300 outline-none text-gray-700 font-bold tracking-wider" />
                 <p className="mt-3 text-xs text-purple-600/70 flex items-start gap-1">
                   <ShieldAlert size={14} className="mt-0.5 shrink-0" /> 修改後請務必記住新密碼。
                 </p>
              </div>

              <div className="bg-gray-50 p-6 rounded-3xl text-sm text-gray-600 border border-gray-100">
                <p className="font-bold mb-3 text-gray-800">班表規則說明</p>
                <ul className="space-y-2 list-none">
                  <li className="flex gap-2"><span className="w-1.5 h-1.5 rounded-full bg-red-400 mt-1.5"></span> 週日/國定假日：10:00 - 17:00</li>
                  <li className="flex gap-2"><span className="w-1.5 h-1.5 rounded-full bg-green-400 mt-1.5"></span> 週六：10:00 - 18:00</li>
                  <li className="flex gap-2"><span className="w-1.5 h-1.5 rounded-full bg-blue-400 mt-1.5"></span> 平日：10:00 - 18:00</li>
                </ul>
              </div>

              <button onClick={handleSaveSettings}
                className="w-full bg-gray-800 text-white py-4 rounded-2xl font-bold hover:bg-black shadow-xl hover:shadow-2xl hover:-translate-y-1 transition-all flex items-center justify-center gap-2">
                <Save size={20} /> 儲存並同步設定
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useMemo } from 'react';
import { AppData, User, UserRole } from '../types';
import { BarChart3, Trophy } from 'lucide-react';

interface StatsSidebarProps {
  currentDate: Date;
  data: AppData;
}

const StatsSidebar: React.FC<StatsSidebarProps> = ({ currentDate, data }) => {
  const students = data.users.filter(u => u.role === UserRole.STUDENT);
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  // Calculate stats for the current month
  const stats = useMemo(() => {
    const counts: Record<string, number> = {};
    const currentMonthPrefix = `${year}-${String(month + 1).padStart(2, '0')}`;

    // Initialize 0
    students.forEach(s => counts[s.id] = 0);

    // Count shifts
    Object.values(data.shifts).forEach(shift => {
      // 1. Filter by current month
      if (!shift.date.startsWith(currentMonthPrefix)) return;

      // 2. If closed, no one works
      if (shift.isClosed) return;

      // 3. Determine the active worker
      // Priority: Confirmed User > Single Signup (Auto-assign)
      let workerId = shift.confirmedUserId;

      if (!workerId && shift.signups && shift.signups.length === 1) {
        workerId = shift.signups[0];
      }

      // 4. Increment count if a worker exists
      if (workerId) {
        counts[workerId] = (counts[workerId] || 0) + 1;
      }
    });

    // Sort by count descending
    return students
      .map(s => ({ user: s, count: counts[s.id] || 0 }))
      .sort((a, b) => b.count - a.count);
  }, [data.shifts, students, year, month]);

  const totalShifts = stats.reduce((acc, curr) => acc + curr.count, 0);

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-gray-100 p-6 sticky top-24">
      <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
        <div className="p-2.5 bg-orange-100 text-orange-500 rounded-xl">
          <BarChart3 size={20} />
        </div>
        <div>
          <h3 className="font-bold text-gray-800 text-lg">{month + 1}月 排班統計</h3>
          <p className="text-xs text-gray-400 font-bold">Total: {totalShifts} 班</p>
        </div>
      </div>

      <div className="space-y-3">
        {stats.map((item, index) => (
          <div key={item.user.id} className="group flex items-center justify-between p-3 rounded-2xl hover:bg-gray-50 transition-colors border border-transparent hover:border-gray-100">
            <div className="flex items-center gap-3">
              <div className="relative">
                <span className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold shadow-sm text-gray-700 ${item.user.color.replace('bg-', 'bg-opacity-50 bg-')}`}>
                  {item.user.name[0]}
                </span>
                {index === 0 && item.count > 0 && (
                  <div className="absolute -top-1 -right-1 bg-yellow-400 text-white rounded-full p-0.5 border-2 border-white shadow-sm">
                    <Trophy size={10} />
                  </div>
                )}
              </div>
              <span className="font-bold text-gray-700 group-hover:text-blue-600 transition-colors">
                {item.user.name}
              </span>
            </div>

            <div className="flex items-center gap-2">
              <div className="h-2 w-16 bg-gray-100 rounded-full overflow-hidden hidden xl:block">
                <div 
                  className={`h-full rounded-full ${item.user.color.split(' ')[0]}`} 
                  style={{ width: `${totalShifts > 0 ? (item.count / totalShifts) * 100 : 0}%` }}
                ></div>
              </div>
              <span className={`text-sm font-bold px-2.5 py-1 rounded-lg ${item.count > 0 ? 'bg-gray-800 text-white' : 'bg-gray-100 text-gray-400'}`}>
                {item.count}
              </span>
            </div>
          </div>
        ))}

        {students.length === 0 && (
          <div className="text-center text-gray-400 py-4 text-sm">
            無工讀生資料
          </div>
        )}
      </div>
    </div>
  );
};

export default StatsSidebar;

import React, { useState, useEffect } from 'react';
import { User, AppData, UserRole } from './types';
import { fetchAppData, sendAction } from './services/api';
import Login from './components/Login';
import Calendar from './components/Calendar';
import AdminPanel from './components/AdminPanel';
import PrintView from './components/PrintView';
import StatsSidebar from './components/StatsSidebar';
import { LogOut, Printer, RefreshCw, UserCheck, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [data, setData] = useState<AppData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [syncing, setSyncing] = useState<boolean>(false);
  const [currentDate, setCurrentDate] = useState<Date>(new Date());
  const [showPrintView, setShowPrintView] = useState(false);

  const [selectedAdminDate, setSelectedAdminDate] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setLoading(false);
  };

  const handleSync = async () => {
    setSyncing(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setSyncing(false);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setSelectedAdminDate(null);
  };

  const handleDateClick = async (dateStr: string) => {
    if (!currentUser || !data) return;

    if (currentUser.role === UserRole.STUDENT) {
      const shift = data.shifts[dateStr];
      if (shift?.isClosed || shift?.confirmedUserId) return; 

      const currentSignups = shift?.signups || [];
      const isSignedUp = currentSignups.includes(currentUser.id);

      const newSignups = isSignedUp 
        ? currentSignups.filter(id => id !== currentUser.id)
        : [...currentSignups, currentUser.id];

      const newData = { ...data, shifts: { ...data.shifts, [dateStr]: { ...shift, date: dateStr, signups: newSignups } } };
      setData(newData);

      await sendAction({
        action: 'toggleSignup',
        payload: { date: dateStr, userId: currentUser.id }
      });
    } else if (currentUser.role === UserRole.ADMIN) {
      setSelectedAdminDate(dateStr);
    }
  };

  const handleAdminShiftAction = async (action: 'confirm' | 'close' | 'clear', targetUserId?: string) => {
    if (!selectedAdminDate || !data) return;

    const shift = data.shifts[selectedAdminDate] || { date: selectedAdminDate, signups: [] };
    let newShift = { ...shift };

    if (action === 'confirm' && targetUserId) {
      newShift.confirmedUserId = targetUserId;
      newShift.isClosed = false;
    } else if (action === 'close') {
      newShift.isClosed = !newShift.isClosed;
      newShift.confirmedUserId = undefined;
    } else if (action === 'clear') {
      newShift.confirmedUserId = undefined;
      newShift.isClosed = false;
    }

    const newData = { ...data, shifts: { ...data.shifts, [selectedAdminDate]: newShift } };
    setData(newData);
    setSelectedAdminDate(null);

    await sendAction({
      action: 'assignShift',
      payload: { date: selectedAdminDate, ...newShift }
    });
  };

  const handleUserUpdate = async (action: 'add' | 'delete', user?: User) => {
    if (!data) return;
    let newUsers = [...data.users];

    if (action === 'add' && user) {
      newUsers.push(user);
    } else if (action === 'delete' && user) {
      newUsers = newUsers.filter(u => String(u.id) !== String(user.id));
    }

    setData({ ...data, users: newUsers });

    await sendAction({
      action: 'manageUser',
      payload: { type: action, user }
    });
  };

  const handleSettingsUpdate = async (newSettings: AppData['settings']) => {
    if (!data) return;
    setData({ ...data, settings: newSettings });

    await sendAction({
      action: 'updateSettings',
      payload: newSettings
    });
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-pink-50">
        <div className="animate-bounce bg-white p-4 rounded-full shadow-lg mb-4">
           <UserCheck size={32} className="text-pink-500" />
        </div>
        <p className="text-gray-500 font-bold animate-pulse">正在為您準備班表...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={data?.users || []} adminPassword={data?.settings.adminPassword} onLogin={handleLogin} />;
  }

  if (showPrintView && data) {
    return <PrintView currentDate={currentDate} data={data} onClose={() => setShowPrintView(false)} />;
  }

  return (
    <div className="min-h-screen pb-12 transition-colors duration-500">
      {/* Top Navbar */}
      <nav className="bg-white/80 backdrop-blur-md border-b border-gray-100 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white shadow-lg ${currentUser.role === UserRole.ADMIN ? 'bg-gradient-to-br from-purple-500 to-indigo-500' : 'bg-gradient-to-br from-blue-400 to-cyan-400'}`}>
                 <span className="font-bold text-lg">{currentUser.name[0]}</span>
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-gray-800 text-lg leading-tight">
                  {currentUser.name}
                </span>
                <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">
                  {currentUser.role === UserRole.ADMIN ? 'Administrator' : 'Student'}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleSync}
                disabled={syncing}
                className={`p-3 rounded-xl transition-all ${syncing ? 'animate-spin text-blue-400' : 'text-gray-400 hover:text-blue-500 hover:bg-blue-50'}`}
                title="同步資料"
              >
                <RefreshCw size={20} />
              </button>
              <button 
                onClick={() => setShowPrintView(true)}
                className="hidden md:flex items-center gap-2 bg-gray-100 hover:bg-gray-800 hover:text-white text-gray-600 px-4 py-2 rounded-xl font-bold transition-all"
              >
                <Printer size={18} /> 列印 / 匯出
              </button>
              <button 
                onClick={handleLogout}
                className="flex items-center gap-2 bg-red-50 hover:bg-red-500 hover:text-white text-red-500 px-4 py-2 rounded-xl font-bold transition-all"
              >
                <LogOut size={18} /> <span className="hidden sm:inline">登出</span>
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Main Grid Layout for Desktop Side-by-Side */}
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">

          {/* Left Column: Calendar (Takes up 3/4 space on desktop) */}
          <div className="lg:col-span-3 space-y-10">
            <section>
              <Calendar 
                currentDate={currentDate}
                data={data!}
                currentUser={currentUser}
                onMonthChange={(inc) => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + inc, 1))}
                onDateClick={handleDateClick}
              />
            </section>

            {currentUser.role === UserRole.ADMIN && (
              <section>
                <div className="flex items-center gap-2 mb-6 ml-2">
                    <div className="h-8 w-1.5 bg-gradient-to-b from-blue-500 to-purple-500 rounded-full"></div>
                    <h2 className="text-2xl font-bold text-gray-800">後台管理中心</h2>
                </div>
                <AdminPanel 
                  data={data!} 
                  onUpdateUser={handleUserUpdate}
                  onUpdateSettings={handleSettingsUpdate}
                />
              </section>
            )}
          </div>

          {/* Right Column: Stats Sidebar (Takes up 1/4 space on desktop, sticky) */}
          <div className="lg:col-span-1">
             {data && (
               <StatsSidebar 
                  currentDate={currentDate}
                  data={data}
               />
             )}
          </div>
        </div>
      </main>

      {/* Admin Shift Management Modal */}
      {selectedAdminDate && data && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden transform scale-100 transition-all">
            <div className="bg-gradient-to-r from-gray-800 to-gray-700 p-6 text-white flex justify-between items-center">
              <div>
                 <h3 className="text-xl font-bold">排班模擬</h3>
                 <p className="text-gray-300 text-sm opacity-80">{selectedAdminDate}</p>
              </div>
              <button onClick={() => setSelectedAdminDate(null)} className="text-white/60 hover:text-white bg-white/10 hover:bg-white/20 p-2 rounded-full transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 space-y-6">
              <div>
                  <h4 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-3">報名人員</h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto pr-1 custom-scrollbar">
                    {(data.shifts[selectedAdminDate]?.signups || []).length === 0 && (
                      <div className="text-center py-6 bg-gray-50 rounded-xl border border-dashed border-gray-200 text-gray-400">
                         尚無人報名
                      </div>
                    )}

                    {(data.shifts[selectedAdminDate]?.signups || []).map(uid => {
                      const u = data.users.find(usr => usr.id === uid);
                      if(!u) return null;

                      const shift = data.shifts[selectedAdminDate];
                      const isConfirmed = shift?.confirmedUserId === uid;
                      // Logic: If NO ONE is explicitly confirmed, and this user is the ONLY signup, treat as Auto-Confirmed
                      const isAutoConfirmed = !shift?.confirmedUserId && shift?.signups.length === 1 && !shift?.isClosed;

                      return (
                        <button
                          key={uid}
                          onClick={() => handleAdminShiftAction('confirm', uid)}
                          className={`w-full flex items-center justify-between p-3 rounded-xl border-2 transition-all group ${
                            isConfirmed 
                              ? 'border-green-500 bg-green-50 shadow-sm' 
                              : isAutoConfirmed
                                ? 'border-blue-400 bg-blue-50 shadow-sm'
                                : 'border-transparent bg-gray-50 hover:bg-blue-50 hover:border-blue-200'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <span className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold shadow-sm ${u.color}`}>
                              {u.name[0]}
                            </span>
                            <span className="font-bold text-gray-700">{u.name}</span>
                          </div>
                          {isConfirmed ? (
                             <span className="text-green-600 text-xs font-bold bg-green-100 px-2 py-1 rounded-full">Formal</span>
                          ) : isAutoConfirmed ? (
                             <span className="text-blue-600 text-xs font-bold bg-blue-100 px-2 py-1 rounded-full">Auto</span>
                          ) : (
                             <span className="text-gray-300 group-hover:text-blue-400 text-xs font-bold">Assign</span>
                          )}
                        </button>
                      );
                    })}
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-3 pt-4 border-t border-gray-100">
                 <button 
                    onClick={() => handleAdminShiftAction('close')}
                    className={`p-3 rounded-xl font-bold border-2 transition-all ${
                      data.shifts[selectedAdminDate]?.isClosed 
                      ? 'bg-red-500 text-white border-red-500 shadow-lg shadow-red-200' 
                      : 'bg-white text-red-500 border-red-100 hover:border-red-300 hover:bg-red-50'
                    }`}
                 >
                   {data.shifts[selectedAdminDate]?.isClosed ? '🔓 解除休診' : '🔒 設為休診'}
                 </button>
                 <button 
                    onClick={() => handleAdminShiftAction('clear')}
                    className="p-3 rounded-xl font-bold bg-gray-100 text-gray-600 hover:bg-gray-200 border-2 border-transparent"
                 >
                   清除指定
                 </button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

payload.text:
這是一個非常關鍵的問題！您的前端 App 已經寫好了，但因為 **Google Apps Script (GAS) 端還沒有對應的程式碼來接收與儲存資料**，所以當您按下「同步」時，前端從雲端抓到了「空資料」或「錯誤」，導致畫面上的資料被清空。

要解決這個問題，您需要完成兩個步驟：

1.  **部署後端程式碼**：將下方的 GAS 程式碼貼到您的 Google Apps Script 專案中。
2.  **初始化資料庫**：我在後台新增了一個「**初始化雲端資料庫**」按鈕。在您部署完後端程式後，請按一下這個按鈕，它會把目前網頁上的預設資料（包含工讀生名單、設定）全部上傳到 Google Sheet，之後按「同步」就不會歸零了。

### 第一步：請將以下程式碼貼入 Google Apps Script (`Code.gs`)

請開啟您的 Google Sheet -> 擴充功能 -> Apps Script，清空內容並貼上：

```javascript
function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const action = e.parameter.action || (e.postData && JSON.parse(e.postData.contents).action);
    const payload = e.postData ? JSON.parse(e.postData.contents).payload : {};

    // 1. 初始化 Tab
    setupSheets(ss);

    let result = {};

    if (action === 'getData') {
      result = getAllData(ss);
    } 
    else if (action === 'initialize') {
      // 強制覆寫所有資料 (用於第一次設定)
      saveAllData(ss, payload);
      result = getAllData(ss);
    }
    else if (action === 'toggleSignup') {
      toggleSignup(ss, payload.date, payload.userId);
      result = getAllData(ss);
    } 
    else if (action === 'assignShift') {
      assignShift(ss, payload.date, payload.confirmedUserId, payload.isClosed);
      result = getAllData(ss);
    }
    else if (action === 'manageUser') {
      manageUser(ss, payload.type, payload.user);
      result = getAllData(ss);
    }
    else if (action === 'updateSettings') {
      updateSettings(ss, payload);
      result = getAllData(ss);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ error: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// 讀取所有資料
function getAllData(ss) {
  const usersSheet = ss.getSheetByName('Users');
  const shiftsSheet = ss.getSheetByName('Shifts');
  const settingsSheet = ss.getSheetByName('Settings');

  // Users
  const usersData = usersSheet.getDataRange().getValues();
  const users = [];
  // Skip header
  for (let i = 1; i < usersData.length; i++) {
    if (usersData[i][0]) {
      users.push({
        id: usersData[i][0],
        name: usersData[i][1],
        password: usersData[i][2],
        color: usersData[i][3],
        role: usersData[i][4]
      });
    }
  }

  // Shifts
  const shiftsData = shiftsSheet.getDataRange().getValues();
  const shifts = {};
  for (let i = 1; i < shiftsData.length; i++) {
    const date = shiftsData[i][0]; // string YYYY-MM-DD
    if (date) {
      shifts[date] = {
        date: date,
        signups: shiftsData[i][1] ? JSON.parse(shiftsData[i][1]) : [],
        confirmedUserId: shiftsData[i][2] || undefined,
        isClosed: shiftsData[i][3] === true || shiftsData[i][3] === 'TRUE'
      };
    }
  }

  // Settings
  const settingsData = settingsSheet.getDataRange().getValues();
  let settings = { holidays: [], adminPassword: 'admin', googleSheetUrl: '' };
  if (settingsData.length > 1) {
    settings = JSON.parse(settingsData[1][0]);
  }

  return { users, shifts, settings };
}

// 儲存全部 (Initialization)
function saveAllData(ss, data) {
  const usersSheet = ss.getSheetByName('Users');
  usersSheet.clearContents();
  usersSheet.appendRow(['ID', 'Name', 'Password', 'Color', 'Role']);
  if (data.users && data.users.length > 0) {
    const userRows = data.users.map(u => [u.id, u.name, u.password, u.color, u.role]);
    usersSheet.getRange(2, 1, userRows.length, 5).setValues(userRows);
  }

  const settingsSheet = ss.getSheetByName('Settings');
  settingsSheet.clearContents();
  settingsSheet.appendRow(['JSON_Settings']);
  settingsSheet.appendRow([JSON.stringify(data.settings)]);

  // Shifts usually preserved or cleared? Let's keep shifts logic separate or clear if empty
  if (data.shifts) {
     const shiftsSheet = ss.getSheetByName('Shifts');
     shiftsSheet.clearContents();
     shiftsSheet.appendRow(['Date', 'Signups_JSON', 'ConfirmedUserID', 'IsClosed']);
     // Convert map to array
     const shiftRows = [];
     Object.values(data.shifts).forEach(s => {
       shiftRows.push([s.date, JSON.stringify(s.signups), s.confirmedUserId || '', s.isClosed || false]);
     });
     if (shiftRows.length > 0) {
       shiftsSheet.getRange(2, 1, shiftRows.length, 4).setValues(shiftRows);
     }
  }
}

// 切換報名
function toggleSignup(ss, date, userId) {
  const sheet = ss.getSheetByName('Shifts');
  const data = sheet.getDataRange().getValues();
  let rowIndex = -1;

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][0]) === date) {
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex === -1) {
    // New Date
    const signups = [userId];
    sheet.appendRow([date, JSON.stringify(signups), '', false]);
  } else {
    // Update Date
    const currentJSON = data[rowIndex - 1][1];
    let signups = currentJSON ? JSON.parse(currentJSON) : [];
    if (signups.includes(userId)) {
      signups = signups.filter(id => id !== userId);
    } else {
      signups.push(userId);
    }
    sheet.getRange(rowIndex, 2).setValue(JSON.stringify(signups));
  }
}

// 排班操作
function assignShift(ss, date, confirmedUserId, isClosed) {
  const sheet = ss.getSheetByName('Shifts');
  const data = sheet.getDataRange().getValues();
  let rowIndex = -1;

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][0]) === date) {
      rowIndex = i + 1;
      break;
    }
  }

  if (rowIndex === -1) {
    sheet.appendRow([date, '[]', confirmedUserId || '', isClosed]);
  } else {
    sheet.getRange(rowIndex, 3).setValue(confirmedUserId || '');
    sheet.getRange(rowIndex, 4).setValue(isClosed);
  }
}

// 管理人員
function manageUser(ss, type, user) {
  const sheet = ss.getSheetByName('Users');
  if (type === 'add') {
    sheet.appendRow([user.id, user.name, user.password, user.color, user.role]);
  } else if (type === 'delete') {
    const data = sheet.getDataRange().getValues();
    for (let i = 1; i < data.length; i++) {
      if (String(data[i][0]) === String(user.id)) {
        sheet.deleteRow(i + 1);
        break;
      }
    }
  }
}

// 更新設定
function updateSettings(ss, newSettings) {
  const sheet = ss.getSheetByName('Settings');
  sheet.getRange(2, 1).setValue(JSON.stringify(newSettings));
}

function setupSheets(ss) {
  ['Users', 'Shifts', 'Settings'].forEach(name => {
    if (!ss.getSheetByName(name)) {
      const s = ss.insertSheet(name);
      if (name === 'Users') s.appendRow(['ID', 'Name', 'Password', 'Color', 'Role']);
      if (name === 'Shifts') s.appendRow(['Date', 'Signups_JSON', 'ConfirmedUserID', 'IsClosed']);
      if (name === 'Settings') s.appendRow(['JSON_Settings']);
    }
  });
}
