            {currentUser.role === UserRole.ADMIN && (
              <section>
                <div className="flex items-center gap-2 mb-6 ml-2">
                    <div className="h-8 w-1.5 bg-gradient-to-b from-blue-500 to-purple-500 rounded-full"></div>
                    <h2 className="text-2xl font-bold text-gray-800">後台管理中心</h2>
                </div>
                <AdminPanel 
                  data={data!} 
                  onUpdateUser={handleUserUpdate}
                  onUpdateSettings={handleSettingsUpdate}
                  onInitializeCloud={handleInitializeCloud}
                />
              </section>
            )}
          </div>

          {/* Right Column: Stats Sidebar (Takes up 1/4 space on desktop, sticky) */}
          <div className="lg:col-span-1">
             {data && (
               <StatsSidebar 
                  currentDate={currentDate}
                  data={data}
               />
             )}
          </div>
        </div>
      </main>

      {/* Admin Shift Management Modal */}
      {selectedAdminDate && data && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden transform scale-100 transition-all">
            <div className="bg-gradient-to-r from-gray-800 to-gray-700 p-6 text-white flex justify-between items-center">
              <div>
                 <h3 className="text-xl font-bold">排班模擬</h3>
                 <p className="text-gray-300 text-sm opacity-80">{selectedAdminDate}</p>
              </div>
              <button onClick={() => setSelectedAdminDate(null)} className="text-white/60 hover:text-white bg-white/10 hover:bg-white/20 p-2 rounded-full transition-all">
                <X size={20} />
              </button>
            </div>

            <div className="p-6 space-y-6">
              <div>
                  <h4 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-3">報名人員</h4>
                  <div className="space-y-2 max-h-60 overflow-y-auto pr-1 custom-scrollbar">
                    {(data.shifts[selectedAdminDate]?.signups || []).length === 0 && (
                      <div className="text-center py-6 bg-gray-50 rounded-xl border border-dashed border-gray-200 text-gray-400">
                         尚無人報名
                      </div>
                    )}

                    {(data.shifts[selectedAdminDate]?.signups || []).map(uid => {
                      const u = data.users.find(usr => usr.id === uid);
                      if(!u) return null;

                      const shift = data.shifts[selectedAdminDate];
                      const isConfirmed = shift?.confirmedUserId === uid;
                      // Logic: If NO ONE is explicitly confirmed, and this user is the ONLY signup, treat as Auto-Confirmed
                      const isAutoConfirmed = !shift?.confirmedUserId && shift?.signups.length === 1 && !shift?.isClosed;

                      return (
                        <button
                          key={uid}
                          onClick={() => handleAdminShiftAction('confirm', uid)}
                          className={`w-full flex items-center justify-between p-3 rounded-xl border-2 transition-all group ${
                            isConfirmed 
                              ? 'border-green-500 bg-green-50 shadow-sm' 
                              : isAutoConfirmed
                                ? 'border-blue-400 bg-blue-50 shadow-sm'
                                : 'border-transparent bg-gray-50 hover:bg-blue-50 hover:border-blue-200'
                          }`}
                        >
                          <div className="flex items-center gap-3">
                            <span className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold shadow-sm ${u.color}`}>
                              {u.name[0]}
                            </span>
                            <span className="font-bold text-gray-700">{u.name}</span>
                          </div>
                          {isConfirmed ? (
                             <span className="text-green-600 text-xs font-bold bg-green-100 px-2 py-1 rounded-full">Formal</span>
                          ) : isAutoConfirmed ? (
                             <span className="text-blue-600 text-xs font-bold bg-blue-100 px-2 py-1 rounded-full">Auto</span>
                          ) : (
                             <span className="text-gray-300 group-hover:text-blue-400 text-xs font-bold">Assign</span>
                          )}
                        </button>
                      );
                    })}
                  </div>
              </div>

              <div className="grid grid-cols-2 gap-3 pt-4 border-t border-gray-100">
                 <button 
                    onClick={() => handleAdminShiftAction('close')}
                    className={`p-3 rounded-xl font-bold border-2 transition-all ${
                      data.shifts[selectedAdminDate]?.isClosed 
                      ? 'bg-red-500 text-white border-red-500 shadow-lg shadow-red-200' 
                      : 'bg-white text-red-500 border-red-100 hover:border-red-300 hover:bg-red-50'
                    }`}
                 >
                   {data.shifts[selectedAdminDate]?.isClosed ? '🔓 解除休診' : '🔒 設為休診'}
                 </button>
                 <button 
                    onClick={() => handleAdminShiftAction('clear')}
                    className="p-3 rounded-xl font-bold bg-gray-100 text-gray-600 hover:bg-gray-200 border-2 border-transparent"
                 >
                   清除指定
                 </button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React from 'react';
import { AppData, User, ShiftDay, UserRole } from '../types';
import { DEFAULT_WORKER_NAME, WEEKDAYS } from '../constants';
import { Check, Lock, Calendar as CalendarIcon, ChevronLeft, ChevronRight, CloudOff } from 'lucide-react';

interface CalendarProps {
  currentDate: Date;
  data: AppData;
  currentUser: User | null;
  onMonthChange: (increment: number) => void;
  onDateClick: (dateStr: string) => void;
  pendingDates?: Set<string>; // New prop to track unsaved dates
}

const Calendar: React.FC<CalendarProps> = ({ 
  currentDate, 
  data, 
  currentUser, 
  onMonthChange, 
  onDateClick,
  pendingDates = new Set()
}) => {

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const formatDate = (y: number, m: number, d: number) => {
    return `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  };

  const getDayDetails = (day: number) => {
    const dateStr = formatDate(year, month, day);
    const dateObj = new Date(year, month, day);
    const dayOfWeek = dateObj.getDay();

    const isHoliday = data.settings.holidays.includes(dateStr);
    const isSunday = dayOfWeek === 0;
    const isSaturday = dayOfWeek === 6;

    let dateStyle = 'text-gray-600 bg-white border-gray-100'; 
    let badge = null;

    if (isSunday || isHoliday) {
      dateStyle = 'text-red-600 bg-red-50/50 border-red-100';
      badge = isHoliday ? <span className="absolute -top-2 -right-2 bg-red-400 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm z-10">假</span> : null;
    } else if (isSaturday) {
      dateStyle = 'text-green-600 bg-green-50/50 border-green-100';
    }

    const shift: ShiftDay | undefined = data.shifts[dateStr];
    const signups = shift?.signups || [];
    const confirmedId = shift?.confirmedUserId;
    const isClosed = shift?.isClosed;
    const isPending = pendingDates.has(dateStr);

    return { dateStr, day, dayOfWeek, isHoliday, isSunday, isSaturday, dateStyle, badge, signups, confirmedId, isClosed, isPending };
  };

  const renderCellContent = (details: ReturnType<typeof getDayDetails>) => {
    const { signups, confirmedId, isClosed, isSunday, isHoliday, isSaturday } = details;

    if (isClosed) {
      return (
        <div className="flex flex-col items-center justify-center flex-1 opacity-50">
          <Lock size={16} className="text-gray-400 mb-1" />
          <span className="text-gray-400 font-bold text-sm tracking-widest">休診</span>
        </div>
      );
    }

    // Time Display
    let timeText = '10:00-18:00';
    if (isSunday || isHoliday) timeText = '10:00-17:00';

    const TimeBadge = () => (
       <div className={`text-[10px] mb-1 font-medium text-center ${isSunday||isHoliday ? 'text-red-500' : isSaturday ? 'text-green-600' : 'text-gray-400'}`}>
         {timeText}
       </div>
    );

    // Logic: Confirmed user OR Single Signup (Auto-confirmed visually)
    const activeUserId = confirmedId || (signups.length === 1 ? signups[0] : null);

    if (activeUserId) {
      const user = data.users.find(u => u.id === activeUserId);
      if (user) {
        return (
          <div className="flex flex-col h-full justify-between pb-1">
            <TimeBadge />
            <div className={`py-3 px-1 rounded-xl text-base font-bold w-full text-center shadow-sm border border-white/50 ${user.color} flex flex-col items-center justify-center`}>
               <span className="truncate w-full leading-none">{user.name}</span>
            </div>
          </div>
        );
      }
    } else if (signups.length === 0) {
      return (
        <div className="flex flex-col h-full justify-between pb-1">
          <TimeBadge />
          <div className="py-2 px-1 rounded-xl text-sm font-medium w-full text-center bg-gray-100 text-gray-400 border border-gray-200 border-dashed">
            {DEFAULT_WORKER_NAME}
          </div>
        </div>
      );
    } else {
      return (
        <div className="flex flex-col h-full justify-between pb-1">
          <TimeBadge />
          <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-1 text-center">
            <div className="text-xs text-yellow-600 font-bold mb-1">{signups.length} 人報名</div>
            <div className="flex flex-wrap gap-1 justify-center h-5 overflow-hidden">
               {signups.map(uid => {
                 const u = data.users.find(usr => usr.id === uid);
                 return u ? <div key={uid} className={`w-1.5 h-1.5 rounded-full ${u.color.split(' ')[0]}`} /> : null;
               })}
            </div>
          </div>
        </div>
      );
    }
    return null;
  };

  const calendarCells = [];

  for (let i = 0; i < firstDayOfMonth; i++) {
    calendarCells.push(<div key={`empty-${i}`} className="min-h-[140px]" />);
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const details = getDayDetails(d);
    const isInteractable = currentUser?.role === UserRole.STUDENT && !details.isClosed && !details.confirmedId;
    const isAdmin = currentUser?.role === UserRole.ADMIN;
    const isSignedUp = details.signups.includes(currentUser?.id || '');

    calendarCells.push(
      <div 
        key={details.dateStr} 
        onClick={() => {
           if (isAdmin || isInteractable) onDateClick(details.dateStr);
        }}
        className={`
          relative min-h-[140px] p-2 rounded-2xl border transition-all duration-300 group
          flex flex-col
          ${details.dateStyle}
          ${isInteractable ? 'cursor-pointer hover:-translate-y-1 hover:shadow-lg' : ''}
          ${isAdmin ? 'cursor-pointer hover:border-blue-300 hover:shadow-md' : ''}
          ${isSignedUp && !isAdmin ? 'ring-2 ring-blue-300 bg-blue-50/80' : ''}
          ${!isInteractable && !isAdmin ? 'opacity-90' : ''}
          ${details.isPending ? 'ring-2 ring-orange-400 border-orange-300 bg-orange-50' : ''} 
        `}
      >
        {details.badge}
        {details.isPending && (
            <div className="absolute -top-2 -left-2 bg-orange-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm z-10 flex items-center gap-1 animate-pulse">
                <CloudOff size={10} /> 未儲存
            </div>
        )}

        <div className="flex justify-between items-center mb-1">
          <span className="text-xl font-bold font-quicksand">{d}</span>
          {isSignedUp && !isAdmin && <Check size={16} className="text-blue-500" strokeWidth={3} />}
          {isAdmin && details.signups.length > 0 && !details.confirmedId && (
            <div className="w-2 h-2 bg-yellow-400 rounded-full animate-pulse"></div>
          )}
        </div>

        {renderCellContent(details)}

        {/* Hover Action hint for Student */}
        {isInteractable && (
          <div className="absolute inset-0 bg-blue-500/5 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
             <span className="text-blue-600 font-bold text-xs bg-white/80 px-2 py-1 rounded-full shadow-sm">
               {isSignedUp ? '取消報名' : '點擊報名'}
             </span>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header Card */}
      <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-6 flex flex-col md:flex-row items-center justify-between gap-4">
         <div className="flex items-center gap-4">
           <div className="p-3 bg-blue-100 text-blue-600 rounded-2xl">
             <CalendarIcon size={24} />
           </div>
           <div>
             <h2 className="text-3xl font-bold text-gray-800 tracking-tight font-quicksand">
               {year} <span className="text-gray-300">/</span> {String(month + 1).padStart(2, '0')}
             </h2>
             <p className="text-gray-400 text-sm font-medium">Monthly Schedule</p>
           </div>
         </div>

         <div className="flex items-center gap-2 bg-gray-50 p-1.5 rounded-2xl">
           <button onClick={() => onMonthChange(-1)} className="p-3 hover:bg-white hover:shadow-md rounded-xl transition-all text-gray-600">
             <ChevronLeft size={20} />
           </button>
           <div className="h-6 w-px bg-gray-200 mx-2"></div>
           <button onClick={() => onMonthChange(1)} className="p-3 hover:bg-white hover:shadow-md rounded-xl transition-all text-gray-600">
             <ChevronRight size={20} />
           </button>
         </div>
      </div>

      {/* Grid */}
      <div className="bg-white rounded-3xl shadow-xl border border-gray-100 p-4 md:p-6">
        <div className="grid grid-cols-7 mb-4">
          {WEEKDAYS.map((day, idx) => (
            <div key={day} className={`text-center font-bold text-sm pb-2 border-b-2 border-transparent ${
              idx === 0 ? 'text-red-400' : idx === 6 ? 'text-green-500' : 'text-gray-400'
            }`}>
              {day}
            </div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-2 md:gap-3">
          {calendarCells}
        </div>
      </div>
    </div>
  );
};

export default Calendar;

import React, { useState, useEffect } from 'react';
import { User, AppData, UserRole } from './types';
import { fetchAppData, sendAction } from './services/api';
import Login from './components/Login';
import Calendar from './components/Calendar';
import AdminPanel from './components/AdminPanel';
import PrintView from './components/PrintView';
import StatsSidebar from './components/StatsSidebar';
import { LogOut, Printer, RefreshCw, UserCheck, X, CloudUpload, AlertCircle, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [data, setData] = useState<AppData | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [syncing, setSyncing] = useState<boolean>(false);
  const [currentDate, setCurrentDate] = useState<Date>(new Date());
  const [showPrintView, setShowPrintView] = useState(false);

  // Batch Save State for Students
  const [unsavedActions, setUnsavedActions] = useState<{date: string, userId: string}[]>([]);
  const [isSavingChanges, setIsSavingChanges] = useState(false);

  const [selectedAdminDate, setSelectedAdminDate] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setUnsavedActions([]); // Clear unsaved on reload
    setLoading(false);
  };

  const handleSync = async () => {
    if (unsavedActions.length > 0) {
        if (!confirm("您有未儲存的變更，同步將會遺失這些修改。確定要同步嗎？")) return;
    }
    setSyncing(true);
    const fetchedData = await fetchAppData();
    setData(fetchedData);
    setUnsavedActions([]);
    setSyncing(false);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setUnsavedActions([]); // Reset state on new login
  };

  const handleLogout = () => {
    if (unsavedActions.length > 0) {
       if(!confirm("您有未儲存的變更，登出將會遺失這些修改。確定要登出嗎？")) return;
    }
    setCurrentUser(null);
    setSelectedAdminDate(null);
    setUnsavedActions([]);
  };

  const handleDateClick = async (dateStr: string) => {
    if (!currentUser || !data) return;

    if (currentUser.role === UserRole.STUDENT) {
      const shift = data.shifts[dateStr];
      if (shift?.isClosed || shift?.confirmedUserId) return; 

      const currentSignups = shift?.signups || [];
      const isSignedUp = currentSignups.includes(currentUser.id);

      const newSignups = isSignedUp 
        ? currentSignups.filter(id => id !== currentUser.id)
        : [...currentSignups, currentUser.id];

      // Optimistic Update (Local Only)
      const newData = { ...data, shifts: { ...data.shifts, [dateStr]: { ...shift, date: dateStr, signups: newSignups } } };
      setData(newData);

      // Queue Action
      setUnsavedActions(prev => [...prev, { date: dateStr, userId: currentUser.id }]);

    } else if (currentUser.role === UserRole.ADMIN) {
      setSelectedAdminDate(dateStr);
    }
  };

  const handleSaveChanges = async () => {
      if (unsavedActions.length === 0) return;

      setIsSavingChanges(true);

      // Process queue sequentially to ensure GAS consistency
      // Note: A batch endpoint in GAS would be faster, but sequential is safer with existing setup.
      const uniqueDates = Array.from(new Set(unsavedActions.map(a => a.date)));
      let successCount = 0;

      // We process the QUEUE by simply sending the toggle requests. 
      // Since toggle is relative, we rely on the logic that the user clicked X times locally.
      // However, a safer way for data integrity with the current `toggleSignup` API 
      // is to just process the actions in order.

      for (let i = 0; i < unsavedActions.length; i++) {
          const action = unsavedActions[i];
          const result = await sendAction({
             action: 'toggleSignup',
             payload: { date: action.date, userId: action.userId }
          });
          if (result) successCount++;
      }

      if (successCount === unsavedActions.length) {
          // Fetch fresh data to ensure we are in sync
          const finalData = await fetchAppData();
          setData(finalData);
          setUnsavedActions([]);
          alert("所有變更已成功儲存並上傳至雲端！");
      } else {
          alert(`儲存部分失敗 (${successCount}/${unsavedActions.length})。請檢查網路連線並重試。`);
          // We don't clear unsaved actions so user can try again, 
          // but we should probably reload data to see what stuck.
          const partialData = await fetchAppData();
          setData(partialData);
          setUnsavedActions([]); // Clear for now to avoid state mismatch hell
      }

      setIsSavingChanges(false);
  };

  const handleAdminShiftAction = async (action: 'confirm' | 'close' | 'clear', targetUserId?: string) => {
    if (!selectedAdminDate || !data) return;

    const shift = data.shifts[selectedAdminDate] || { date: selectedAdminDate, signups: [] };
    let newShift = { ...shift };

    if (action === 'confirm' && targetUserId) {
      newShift.confirmedUserId = targetUserId;
      newShift.isClosed = false;
    } else if (action === 'close') {
      newShift.isClosed = !newShift.isClosed;
      newShift.confirmedUserId = undefined;
    } else if (action === 'clear') {
      newShift.confirmedUserId = undefined;
      newShift.isClosed = false;
    }

    const newData = { ...data, shifts: { ...data.shifts, [selectedAdminDate]: newShift } };
    setData(newData);
    setSelectedAdminDate(null);

    await sendAction({
      action: 'assignShift',
      payload: { date: selectedAdminDate, ...newShift }
    });
  };

  const handleUserUpdate = async (action: 'add' | 'delete', user?: User) => {
    if (!data) return;
    let newUsers = [...data.users];

    if (action === 'add' && user) {
      newUsers.push(user);
    } else if (action === 'delete' && user) {
      newUsers = newUsers.filter(u => String(u.id) !== String(user.id));
    }

    setData({ ...data, users: newUsers });

    await sendAction({
      action: 'manageUser',
      payload: { type: action, user }
    });
  };

  const handleSettingsUpdate = async (newSettings: AppData['settings']) => {
    if (!data) return;
    setData({ ...data, settings: newSettings });

    await sendAction({
      action: 'updateSettings',
      payload: newSettings
    });
  };

  const handleInitializeCloud = async () => {
    if (!data) return;
    setSyncing(true);
    try {
        const result = await sendAction({
            action: 'initialize',
            payload: data
        });
        if (result) {
            setData(result);
            alert("初始化成功！您的資料已安全上傳至 Google Sheet。");
        } else {
            alert("上傳失敗，請檢查網際網路或 Apps Script 部署網址。");
        }
    } catch (e) {
        alert("錯誤: " + e);
    }
    setSyncing(false);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-pink-50">
        <div className="animate-bounce bg-white p-4 rounded-full shadow-lg mb-4">
           <UserCheck size={32} className="text-pink-500" />
        </div>
        <p className="text-gray-500 font-bold animate-pulse">正在為您準備班表...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={data?.users || []} adminPassword={data?.settings.adminPassword} onLogin={handleLogin} />;
  }

  if (showPrintView && data) {
    return <PrintView currentDate={currentDate} data={data} onClose={() => setShowPrintView(false)} />;
  }

  return (
    <div className="min-h-screen pb-24 transition-colors duration-500">
      {/* Top Navbar */}
      <nav className="bg-white/80 backdrop-blur-md border-b border-gray-100 sticky top-0 z-40 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-3">
              <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white shadow-lg ${currentUser.role === UserRole.ADMIN ? 'bg-gradient-to-br from-purple-500 to-indigo-500' : 'bg-gradient-to-br from-blue-400 to-cyan-400'}`}>
                 <span className="font-bold text-lg">{currentUser.name[0]}</span>
              </div>
              <div className="flex flex-col">
                <span className="font-bold text-gray-800 text-lg leading-tight">
                  {currentUser.name}
                </span>
                <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">
                  {currentUser.role === UserRole.ADMIN ? 'Administrator' : 'Student'}
                </span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <button 
                onClick={handleSync}
                disabled={syncing || isSavingChanges}
                className={`p-3 rounded-xl transition-all ${syncing ? 'animate-spin text-blue-400' : 'text-gray-400 hover:text-blue-500 hover:bg-blue-50'}`}
                title="同步資料"
              >
                <RefreshCw size={20} />
              </button>
              <button 
                onClick={() => setShowPrintView(true)}
                className="hidden md:flex items-center gap-2 bg-gray-100 hover:bg-gray-800 hover:text-white text-gray-600 px-4 py-2 rounded-xl font-bold transition-all"
              >
                <Printer size={18} /> 列印 / 匯出
              </button>
              <button 
                onClick={handleLogout}
                className="flex items-center gap-2 bg-red-50 hover:bg-red-500 hover:text-white text-red-500 px-4 py-2 rounded-xl font-bold transition-all"
              >
                <LogOut size={18} /> <span className="hidden sm:inline">登出</span>
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Main Grid Layout for Desktop Side-by-Side */}
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">

          {/* Left Column: Calendar (Takes up 3/4 space on desktop) */}
          <div className="lg:col-span-3 space-y-10">
            <section>
              <Calendar 
                currentDate={currentDate}
                data={data!}
                currentUser={currentUser}
                onMonthChange={(inc) => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + inc, 1))}
                onDateClick={handleDateClick}
                pendingDates={new Set(unsavedActions.map(a => a.date))}
