                    <h2 className="text-2xl font-bold text-gray-800">後台管理中心</h2>
                </div>
                <AdminPanel 
                  data={data!} 
                  onUpdateUser={handleUserUpdate}
                  onUpdateSettings={handleSettingsUpdate}
                  onInitializeCloud={handleInitializeCloud}
                />
